#define ll long long
using namespace std;
const int MAXN=4e5+5,MOD=998244353;
const ll inf=1e18;
struct info { ll z,c; } f[MAXN];
void operator +=(info&u,const info&v) {
	if(v.z<u.z) u=v;
	else if(v.z==u.z) u.c=(u.c+v.c)%MOD;
}
int n,m,D,a[MAXN],b[MAXN],c[MAXN],h[MAXN],p[MAXN];
ll s[MAXN];
info sol(int k) {
	int L=0,R=n;
	for(;L<=R&&c[L]!=k;++L);
	for(;L<=R&&c[R]!=c[n]+k;--R);
	if(L>R) return {inf,0};
	f[L]={0,1};
	for(int i=L+1;i<=R;++i) {
		f[i]=b[i]>0?f[i-1]:info{inf,0};
		if(p[i]>=L) f[i]+={f[p[i]].z+abs(s[i]-s[p[i]]),f[p[i]].c};
	}
	return {f[R].z+abs(s[n]-s[R]+s[L]+1ll*k*D),f[R].c};
}
signed main() {
	ios::sync_with_stdio(false),cin.tie(0),cout.tie(0);
	cin>>D>>n>>m,n+=m;
	memset(h,-1,sizeof(h)),h[m]=0;
	for(int i=1;i<=n;++i) {
		char o; cin>>a[i]>>o;
		b[i]=(o=='H'?1:-1),c[i]=c[i-1]+b[i];
		p[i]=h[c[i]+m],h[c[i]+m]=i,s[i]=s[i-1]+b[i]*a[i];
	}
	int l=*min_element(c,c+n+1),r=*max_element(c+1,c+n+1)-c[n];
	for(int k=1<<20;k;k>>=1) if(l+k<=r&&sol(l+k).z<sol(l+k-1).z) l+=k;
	auto z=sol(l);
	for(int t=l+1;t<=min(l+5,r);++t) z+=sol(t);
	cout<<z.z<<"\n"<<z.c<<"\n";
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
constexpr int N = 13;
constexpr char id[3] = {'o', 'g', 'r'};
char s[4][N], t[4][N];
vector<pair<char, int>> ans;
inline void work (int i, int x) 
{
	ans.emplace_back(id[i], x);
	for (int j = 0; j <= 9; ++j)
		t[i][(j + x) % 10] = s[i][j];
	for (int j = 0; j <= 9; ++j)
		s[i][j] = t[i][j];
	return ;
}
inline void cork(int x) 
{
	ans.emplace_back('c', x);
	for (int i = 0; i < 3; ++i)
		for (int j = 0; j < 3; ++j)
			t[(i + 3 - x) % 3][j] = s[i][j];
	for (int i = 0; i < 3; ++i)
		for (int j = 0; j < 3; ++j)
			s[i][j] = t[i][j];
}
inline void Swap(pair<int, int> x, pair<int, int> y) 
{
	if (x.second != 3) work (x.first, (13 - x.second) % 10);
	if (y.second) 
		work(y.first, 10 - y.second);
	int c = (y.first + 3 - x.first) % 3;
	cork(c), work(x.first, 9), cork(3 - c);
}
int main () 
{
	for (int i = 0; i < 3; ++i)
		cin >> s[i];
	while (1) 
	{
		pair<int, int> x(-1, -1), y(-1, -1);
		for (int i = 0; i < 3; ++i)
			for (int j = 0; j <= 9; ++j)
				if (s[i][j] != id[i]) 
				{
					if (x.first == -1) 
						x = make_pair(i, j);
					else if (s[x.first][x.second] != s[i][j]) 
						y = make_pair(i, j);
				}
		if (x.first == -1) 
			break;
		Swap(x, y);
	}
	cout << ans.size() << '\n';
	for (auto [x, y] : ans) 
		cout << x << y << '\n';
	return 0;
}

