         a += 0.25 * sqrt(4*ss[0]*ss[1]-(ss[0]+ss[1]-ss[2])*(ss[0]+ss[1]-ss[2]));
      }
      if (abs(a-round(a)) > eps)
         cout << 0 << endl ;
      else {
