ll f[N];

double slope(int i,int j){
	if(mx[i]==mx[j]) return f[i]-1ll*mx[i]*i>f[j]-1ll*mx[j]*j?-INF:INF;
	return (long double)(f[i]-1ll*mx[i]*i-f[j]+1ll*mx[j]*j)/(mx[i]-mx[j]);
}

void cdq(int l,int r){
	if(l==r){
		f[l]+=a[l];
		return;
	}
	int mid=(l+r)>>1;
	cdq(l,mid);
	mx[mid]=c[mid],mx[mid+1]=c[mid+1];
	for(int i=mid-1;i>=l;i--) mx[i]=max(mx[i+1],c[i]);
	for(int i=mid+2;i<=r;i++) mx[i]=max(mx[i-1],c[i]);
	for(int i=l;i<=mid;i++) f[mid+1]=min(f[mid+1],f[i]+1ll*(mid+1-i)*mx[i]);
	int ql=1,qr=0,opt=0;
	for(int i=mid+2,j=mid+1;i<=r;i++){
		while(j>l&&mx[j-1]<=mx[i-1]){
			j--;
			while(ql<qr&&(__int128)(f[q[qr]]-f[q[qr-1]])*(j-q[qr])<=(__int128)(f[j]-f[q[qr]])*(q[qr]-q[qr-1])) qr--;
			if(opt>=qr) opt=qr+1;
			q[++qr]=j;
			if(ql==qr) opt=ql;
		}
		while(opt>ql&&f[q[opt-1]]-f[q[opt]]<=1ll*mx[i-1]*(q[opt-1]-q[opt])) opt--;
		if(ql<=qr) f[i]=min(f[i],f[q[opt]]+1ll*(i-q[opt])*mx[i-1]);
	}
	ql=1,qr=0,opt=0;
	for(int i=r,j=l-1;i>=mid+2;i--){
		while(j<mid&&mx[j+1]>=mx[i-1]){
			j++;
			while(ql<qr&&slope(q[qr],q[qr-1])-slope(j,q[qr])<eps) qr--;
			if(opt>=qr) opt=qr+1;
			q[++qr]=j;
			if(ql==qr) opt=ql;
		}
		while(opt>ql&&slope(q[opt],q[opt-1])+i<eps) opt--;
		if(ql<=qr) f[i]=min(f[i],f[q[opt]]+1ll*(i-q[opt])*mx[q[opt]]); 
	}
	cdq(mid+1,r);
}

