struct subtask{
	int n;
	void init(int x)
	{
		n=x;
	}
	int calc(int d1,int d2)
	{
		if(d1>d2) swap(d1,d2);
		int len=n-d1-d2;
		if(d1%len==0) return f[(n-1)/len+1];
		int w=(d1-1)/len+1,x=len-d1%len;
		return min(f[(d2-1)/len+2]+1,f[w+1]+f[(n-1)/((len<<f[w+1])-x)+1]);
	}
}t1,t2;
void update(int x1,int x2,int y1,int y2)
{
	ans=min(ans,t2.calc(x1,m-x2-1)+t1.calc(y1,n-y2-1));
}
