struct Angle {
    int x, y;
    int t;
    Angle(int x=0, int y=0, int t=0) : x(x), y(y), t(t) {}
    Angle operator-(Angle b) const { return {x-b.x, y-b.y, t}; }
    int half() const {
    assert(x || y);
    return y < 0 || (y == 0 && x < 0);
    }
    Angle t90() const { return {-y, x, t + (half() && x >= 0)}; }
    Angle t180() const { return {-x, -y, t + half()}; }
    Angle t360() const { return {x, y, t + 1}; }
};
bool operator<(Angle a, Angle b) {
    // add a . dist2 () and b . dist2 () to also compare distances
    return make_tuple(a.t, a.half(), a.y * (ll)b.x) <
    make_tuple(b.t, b.half(), a.x * (ll)b.y);
}

vector<pair<Angle, int> > ord[205];
int posl[205][205], posr[205][205];
ll dp[205][205], cdp[205][205];

Angle cur[205];
void init(int v) {
    for(int i = 0; i < n; i++) if(i != v) {
        cur[i] = Angle(p[i].x - p[v].x, p[i].y - p[v].y, 0);
        ord[v].push_back(make_pair(cur[i], i));
        ord[v].push_back(make_pair(cur[i].t360(), i));
    }
    sort(ord[v].begin(), ord[v].end());
    for(int i = 0; i < n; i++) if(i != v) {
        posl[v][i] = lower_bound(ord[v].begin(), ord[v].end(), make_pair(cur[i], n)) - ord[v].begin();
        posr[v][i] = upper_bound(ord[v].begin(), ord[v].end(), make_pair(cur[i].t180(), n)) - ord[v].begin();
    }
}

// to be optimized
ll tmp[405];
void trans_i(int l, int r, int v) {
    for(int i = 0; i < 2 * n - 2; i++) {
        int t = ord[v][i].second;
        tmp[i] = t < l || t > r ? -INF : cdp[t][v];
    }
}
void trans_o(int l, int r, int v) {
    for(int i = l; i <= r; i++) {
        cdp[v][i] = -INF;
        if(!ok[v][i]) continue;
        for(int j = posl[v][i]; j < posr[v][i]; j++) cdp[v][i] = max(cdp[v][i], tmp[j]);
        cdp[v][i] += crs[v][i] + w + dp[v + 1][i - 1];
    }
}
ll calc(int l, int r) {
    if(!ok[l][r]) return 0;
    cdp[r][l] = c;
    trans_i(r, r, l);
    trans_o(l + 1, r, l);
    for(int i = l + 1; i < r; i++) {
        trans_i(l, i - 1, i);
        trans_o(i + 1, r, i);
    }
    trans_i(l, r - 1, r);
    trans_o(l, l, r);
    return cdp[r][l];
}

template<class P>
bool inPolygon(P a, bool strict = true) {
    int cnt = 0;
    rep(i,0,n) {
    P q = p[(i + 1) % n];
    if (onSegment(p[i], q, a)) return !strict;
    //or : i f ( segDist (p [ i ] , q , a) <= eps) return ! s t r i c t ;
    cnt ^= ((a.y<p[i].y) - (a.y<q.y)) * a.cross(p[i], q) > 0;
    }
    return cnt;
}

