	ll l=1,r=min(u.len,v.len),x=0;
	while(l<=r) {
		ll mid=(l+r)>>1;
		if(u.qhv(mid)==v.qhv(mid)) x=mid,l=mid+1;
		else r=mid-1;
	}
	return x;
}
