			if(S[x].len^S[y].len) return S[x].len<S[y].len;
			return op[x]=='?'&&op[y]=='+';
		}
		return S[x].qc(k+1)<S[y].qc(k+1);
	});
	for(int i=1;i<=q;++i) {
		st[id[i]]=i;
		const String &str=S[id[i]];
		int l=i+1,r=q,k=i;
