namespace T2{
	int ch[600005][2],siz[600005],sz[600005],sum[600005];
	bool rev[600005],trev[600005],ndrev[600005];
	bool nroot(int x){return ch[fa[x]][0]==x||ch[fa[x]][1]==x;}
	bool son(int x){return ch[fa[x]][1]==x;}
	void reverse(int x){rev[x]^=1,swap(ch[x][0],ch[x][1]);}
	void totalrev(int x){trev[x]^=1,ndrev[x]^=1;}
	void checkrev(int x){if(ndrev[x]) T1::totalrev(x),ndrev[x]=0;}
	void pushdown(int x){
		lab[ch[x][0]]=lab[ch[x][1]]=lab[x];
		if(rev[x]){
			if(ch[x][0]) reverse(ch[x][0]);
			if(ch[x][1]) reverse(ch[x][1]);
			rev[x]=0;
		}
		if(trev[x]){
			if(ch[x][0]) totalrev(ch[x][0]);
			if(ch[x][1]) totalrev(ch[x][1]);
			trev[x]=0;
		}
	}
	void update(int x){
		assert(x);
		siz[x]=1+siz[ch[x][0]]+siz[ch[x][1]];
		sum[x]=sz[x]+sum[ch[x][0]]+sum[ch[x][1]];
	}
	void pushall(int x){
		if(nroot(x)) pushall(fa[x]);
		pushdown(x);
	}
	void rotate(int x){
		int y=fa[x],z=fa[y],k=son(x),w=ch[x][!k];
		if(nroot(y)) ch[z][son(y)]=x;
		ch[x][!k]=y,ch[y][k]=w;
		if(w) fa[w]=y;
		fa[y]=x,fa[x]=z;
		update(y),update(x);
		if(T1::rt[lab[x]][0]==y) T1::rt[lab[x]][0]=x;
		if(T1::rt[lab[x]][1]==y) T1::rt[lab[x]][1]=x;
	}
	void splay(int x){
		pushall(x);
		while(nroot(x)){
			int y=fa[x];
			if(nroot(y)) rotate(son(x)==son(y)?y:x);
			rotate(x);
		}
	}
	int split(int x,int k){
		if(!x) return 0;
		while(1){
			pushdown(x);
			if(siz[ch[x][0]]+1==k) break;
			if(k<=siz[ch[x][0]]) x=ch[x][0];
			else k-=siz[ch[x][0]]+1,x=ch[x][1];
		}
		splay(x);
		return x;
	}
	int delrt(int x){
		assert(x);
		pushdown(x);
		int tmp[2]={ch[x][0],ch[x][1]};
		if(ch[x][0]) fa[ch[x][0]]=0,ch[x][0]=0;
		if(ch[x][1]) fa[ch[x][1]]=0,ch[x][1]=0;
		if(!tmp[0]) return -tmp[1]-1;
		int y=tmp[0]; pushdown(y);
		while(ch[y][1]) y=ch[y][1],pushdown(y);
		splay(y);
		ch[y][1]=tmp[1],fa[tmp[1]]=y;
		update(y);
		return y;
	}
	int addrt(int x,int y){
		if(x) pushdown(x);
		if(ch[x][1]) ch[y][1]=ch[x][1],fa[ch[x][1]]=y,ch[x][1]=0;
		if(x) ch[y][0]=x,fa[x]=y;
		if(x) update(x);
		update(y);
		return y;
	}
	int addrt1(int x,int y){
		ch[y][1]=x,fa[x]=y;
		update(y);
		return y;
	}
	int findx(int x,int k){
		pushdown(x);
		if(sum[ch[x][0]]>k) return findx(ch[x][0],k);
		if(sum[ch[x][0]]+sz[x]>k) return x;
		else return findx(ch[x][1],k-sum[ch[x][0]]-sz[x]);
	}
	int kth(int u,int k){
		if(siz[ch[u][0]]+1==k) return u;
		pushdown(u);
		if(k<=siz[ch[u][0]]) return kth(ch[u][0],k);
		else return kth(ch[u][1],k-siz[ch[u][0]]-1);
	}
}

int build(int l,int r){
	int u=++cnt;
	if(l==r){
		T1::tp[u]=-1,T1::update(u);
		return u;
	}
	int mid=readint();
	int lson=build(l,mid),rson=build(mid+1,r);

	T1::rt[rson][0]=0,T1::rt[rson][1]=ts[rson];
	if(mid+1!=r) T2::lab[ts[rson]]=rson;

	T1::fa[lson]=u;
	T1::tp[u]=1,T1::ch[u][1]=lson,T1::update(u);
	ts[u]=rson;
	T2::sz[rson]=r-mid;
	if(l!=mid) T2::ch[rson][1]=ts[lson],T2::fa[ts[lson]]=rson;
	T2::update(rson);
	return u;
}

int getf(int x){
	if(x==1) return 0;
	T2::splay(x);
	int u=T2::lab[x];
	bool f=T1::rt[u][1]==x;
	return T1::kth(u,T2::siz[T2::ch[x][0]]+1,f);
