		int tr[2]={T1::rt[x][0],T1::rt[x][1]};
		int tsz[2]={T1::siz[T1::ch[x][0]][0]+(T1::tp[x]==0),T1::siz[T1::ch[x][0]][1]+(T1::tp[x]==1)};
		bool tf[2]={0,0};
		if(tsz[0]) tr[0]=T2::split(tr[0],tsz[0]);
		else tf[0]=1;
		if(tsz[1]) tr[1]=T2::split(tr[1],tsz[1]);
		else tf[1]=1;
		if(T1::ch[x][1]){
			int nxt=T1::ch[x][1]; T1::pushdown(nxt);
			while(T1::ch[nxt][0]) nxt=T1::ch[nxt][0],T1::pushdown(nxt);
			T2::sz[nxt]=getsiz(nxt);
			T1::splay(x);
			if(tr[0]) T2::splay(tr[0]);
			if(tr[1]) T2::splay(tr[1]);
			tr[T1::tp[x]]=T2::delrt(tr[T1::tp[x]]);
			bool fl=0;
			if(tr[T1::tp[x]]<0) fl=1,tr[T1::tp[x]]=-tr[T1::tp[x]]-1;
			if(tf[T1::tp[x]^1]) tr[T1::tp[x]^1]=T2::addrt1(tr[T1::tp[x]^1],nxt);
			else tr[T1::tp[x]^1]=T2::addrt(tr[T1::tp[x]^1],nxt);

			for(int i=0;i<2;i++){
				if(fl&&i==T1::tp[x]) T1::rt[T1::ch[x][1]][i]=tr[i],T2::lab[tr[i]]=T1::ch[x][1],tr[i]=0;
				else if(tr[i]){
					T1::rt[T1::ch[x][1]][i]=T2::ch[tr[i]][1];
					T2::lab[T2::ch[tr[i]][1]]=T1::ch[x][1];
					T2::fa[T2::ch[tr[i]][1]]=0,T2::ch[tr[i]][1]=0;
					T2::update(tr[i]);
