int findx(int x){
	int y=n-x-1;
	int u=root;
	while(1){
		T1::splay(u);
		int v=T1::rt[u][0];
		// cout<<"findx "<<u<<' '<<x<<' '<<y<<' '<<T2::sum[T1::rt[u][0]]<<' '<<T2::sum[T1::rt[u][1]]<<endl;
		if(T2::sum[v]==x) return T1::findrg(u);
		if(T2::sum[v]>x){
			int w=T2::findx(v,x);
			T2::splay(w);
			T2::checkrev(w);
			x-=T2::sum[T2::ch[w][0]];
			int rnk=T2::siz[T2::ch[w][0]]+1;
			int pt=T1::kth(u,rnk,0);
			T1::splay(pt);
			rnk=T1::siz[T1::ch[pt][0]][1];
			int tmp=rnk?T2::kth(T1::rt[u][1],rnk):0;
			if(tmp) T2::splay(tmp);
			y-=T2::sum[T2::ch[tmp][0]]+T2::sz[tmp];
			y-=getsiz(pt)-getsiz(w);
			u=w;
		}
		else{
			v=T1::rt[u][1];
			int w=T2::findx(v,y);
			T2::splay(w);
			T2::checkrev(w);
			y-=T2::sum[T2::ch[w][0]];
			int rnk=T2::siz[T2::ch[w][0]]+1;
			int pt=T1::kth(u,rnk,1);
			T1::splay(pt);
			rnk=T1::siz[T1::ch[pt][0]][0];
			int tmp=rnk?T2::kth(T1::rt[u][0],rnk):0;
			if(tmp) T2::splay(tmp);
			x-=T2::sum[T2::ch[tmp][0]]+T2::sz[tmp];
			x-=getsiz(pt)-getsiz(w);
			u=w;
		}
	}
}

