int qpow(int x,int k){
	int res=1;
	while(k){
		if(k&1)res=1ll*res*x%lpw;
		k>>=1;x=1ll*x*x%lpw;
	}
	return res;
}

void NTT(int L,int *a,int op){
	static ull f[N],w[N];
	for(int i=0;i<L;i++)f[i]=a[r[i]=(r[i>>1]>>1)|(i&1?L>>1:0)];
	for(int d=1;d<L;d<<=1){
		int wd=qpow(op?3:inv3,(lpw-1)/(d+d));
		w[0]=1;
		for(int i=1;i<d;i++)w[i]=1ll*w[i-1]*wd%lpw;
		for(int i=0;i<L;i+=d<<1){
			for(int j=0;j<d;j++){
				int y=1ll*w[j]*f[i|j|d]%lpw;
				f[i|j|d]=f[i|j]-y+lpw;
				f[i|j]+=y;
			}
		}
		if(d==(1<<16))
			for(int i=0;i<L;i++)f[i]%=lpw;
	}
	int inv=qpow(L,lpw-2);
	for(int i=0;i<L;i++)a[i]=1ll*f[i]%lpw*(op?1:inv)%lpw;
}

