int D(int x) { return sw[x]==pw[x]?0:(sw[x]>pw[x]?1:-1); }
ll qpos(int x,ll t) {
	if(ne[x]) return (t-lst[x])&1?a[ne[x]]:a[x];
	return a[x]+(t-lst[x])*dir[x];
}
struct info {
	ll t; int y,vx,vy;
	inline friend bool operator <(const info &x,const info &y) { return x.t>y.t; }
};
priority_queue <info> Q;
void ins(int x,int y,ll t) {
	if(qpos(x,t)==qpos(y,t)) return Q.push({t,y,vis[x],vis[y]});
	int v=dir[x]-dir[y];
	if(v>0) Q.push({t+(qpos(y,t)-qpos(x,t)+v-1)/v,y,vis[x],vis[y]});
}
void nw(int x) {
	if(ne[x]) {
		int y=ne[x];
		ne[x]=ne[y]=0,vis[y]=++vcnt,dir[y]=D(y);
	} vis[x]=++vcnt;
}
void swp(int y) {
	int x=pr[y],l=pr[x],r=sf[y];
	sf[l]=y,pr[y]=l,sf[y]=x,pr[x]=y,sf[x]=r,pr[r]=x;
	pw[y]=pw[l]+w[l],pw[x]=pw[y]+w[y],sw[x]=sw[r]+w[r],sw[y]=sw[x]+w[x];
}
int upd(int x,ll t) {
	if(ne[x]) {
		int y=ne[x];
		if((t-lst[x])&1) {
			swp(a[x]<a[y]?y:x),swap(a[x],a[y]);
			return lst[x]=lst[y]=t,y;
		} else return lst[x]=lst[y]=t,x;
	} else return a[x]+=dir[x]*(t-lst[x]),lst[x]=t,x;
}
void del(int x,int y) {
	dsu[y]=x,w[x]+=w[y],sw[x]-=w[y],sf[x]=sf[y],pr[sf[y]]=x;
}
