void dfs(int u,int fa)
{
	f[u]=1;
	int i,lst=0;p[0][u]=fa;d[u]=d[fa]+1;
	for(i=1;i<=18;++i)p[i][u]=p[i-1][p[i-1][u]];
	for(auto v:e[u])
	{
		dfs(v,u);
		f[u]=f[u]*(f[v]+1)%mod;
		pr[v]=pr[lst]*(f[v]+1)%mod;lst=v;
	}
	lst=0;
	for(int i=e[u].size()-1;i>=0;--i)
	{
		int v=e[u][i];
		sf[v]=sf[lst]*(f[v]+1)%mod;lst=v;
	}
}
void dfs2(int u,int fa)
{
	sm[u]=(sm[fa]+f[u])%mod;
	h[u]=f[u]*(g[u]+1)%mod;
	for(int i=0;i<e[u].size();++i)
	{
		int v=e[u][i];
		g[v]=pr[i==0?0:e[u][i-1]]*sf[i==e[u].size()-1?0:e[u][i+1]]%mod*(g[u]+1)%mod;
		dfs2(v,u);
	}
}
int lca(int u,int v)
{
	int i;
	if(d[u]>d[v])swap(u,v);
	for(i=18;i>=0;--i)
		if(d[u]<=d[v]-(1<<i))
			v=p[i][v];
	if(u==v)return u;
	for(i=18;i>=0;--i)
		if(p[i][u]!=p[i][v])
			{u=p[i][u];v=p[i][v];}
	return p[0][u];
}

