int calc(int k){
	for(int i=0;i<=d;i++)if(x[i]==k)return y[i];
	pre[0]=suf[d]=1;
	for(int i=0;i<d;i++)pre[i+1]=1ll*pre[i]*(k-x[i]+mod)%mod;
	for(int i=d;i>0;i--)suf[i-1]=1ll*suf[i]*(k-x[i]+mod)%mod;
	int ans=0;
	for(int i=0;i<=d;i++){
		ans=(ans+1ll*y[i]*pre[i]%mod*suf[i]%mod*ifac[i]%mod*ifac[d-i]%mod*(d-i&1?mod-1:1))%mod;
	}
	for(int i=1;i<=d;i++)ans=1ll*ans*ifac[2]%mod;
	return ans;
}
int solve1(int a,int b,int x,ll al,ll ar,ll bl,ll br){
	vector<ll>t={al,ar};
	for(ll bt:{bl,br}){
		t.push_back(bt+x*pw[b]+1);
		t.push_back((bt*2+x*pw[b]-x)/11+1);
	}
	auto calc=[&](ll A)->int {
		ll bp=max(bl,A-x*pw[b]),bq=min(br,(11*A+x-x*pw[b]+1)/2);
		if(bp>=bq)return 0;
		ll st=bp-A+x*pw[b],ed=bq-1-A+x*pw[b];
		return (st+ed)%mod*((ed-st+1)%mod)%mod*ifac[2]%mod;
	};
	auto solve=[&](ll L,ll R)->int {
		L=max(L,al),R=min(R,ar),R--;
