			::x[i]=(L+i*2)%mod,y[i]=calc(L+i*2);
		}
		for(int i=1;i<=d;i++)(y[i]+=y[i-1])%=mod;
		int ans=::calc((R-(L%2!=R%2))%mod);
		if(L<R){
			for(int i=0;i<=d;i++){
				::x[i]=(L+i*2+1)%mod,y[i]=calc(L+i*2+1);
			}
			for(int i=1;i<=d;i++)(y[i]+=y[i-1])%=mod;
