ll calc(ll x,ll y,ll w,ll dx,ll dy,ll m)
{
	if(x<y){swap(x,y);swap(dx,dy);}
	if(dx+w<dy){m-=(dy-dx-w)*x;dx=dy-w;}
	if(dy+w<dx){m-=(dx-dy-w)*y;dy=dx-w;}
	ll ret=dx+dy+w;
	if(m<=0)return ret;
	if(m-(dy+w-dx)*x<=0)return ret+(m+x-1)/x;
	m-=(dy+w-dx)*x;dx=dy+w;ret=dx+dy+w;
	ret+=m/(x+y)*2;m%=(x+y);
	if(m>0){m-=y;++ret;}
	if(m>0){m-=x;++ret;}
	return ret;
}
void dfs2(int u,int fa)
{
	for(auto [v,w]:g[u])
		if(v!=fa)
		{
			ll nw;
			nw=(d[v]+w==d[u])?d2[u]:d[u];
			ans=min(ans,calc
			(
