#include <bits/stdc++.h>

#define N 500005
#define inf 0x3f3f3f3f
#define lson l,m,ls[rt]
#define rson m+1,r,rs[rt]

using namespace std;

int m,cnt,tl,d[N],q[N],ls[N*50],rs[N*50],sz[N*50],ans[N],rti[N];
vector<pair<int,int>>g[N];
vector<array<int,3>>qu[N];
vector<int>e[N];
struct mat
{
	int a[2][2];
	mat operator*(mat b)
	{
		mat ans;
		for(int i=0;i<2;++i)
			for(int j=0;j<2;++j)
			{
				ans.a[i][j]=inf;
				for(int k=0;k<2;++k)
					ans.a[i][j]=min(ans.a[i][j],a[i][k]+b.a[k][j]);
			}
		return ans;
	}
}tr[N*50],bs;

void up(int rt){tr[rt]=tr[rs[rt]]*tr[ls[rt]];sz[rt]=sz[ls[rt]]+sz[rs[rt]];}
void updt(int a,mat b,int l,int r,int& rt)
{
	if(!rt)rt=++cnt;
	if(l==r)
	{
		if(sz[rt]==1&&b.a[0][1]!=inf)q[++tl]=l;
		else{tr[rt]=b;sz[rt]=b.a[0][1]!=inf;}
		return;
	}
	int m=(l+r)>>1;
	if(a<=m)updt(a,b,lson);
	else updt(a,b,rson);
	up(rt);
}
void mrg(int l,int r,int& rt,int rt0)
{
	if(!rt||!rt0){rt=max(rt,rt0);return;}if(l==r){q[++tl]=l;return;}
	int m=(l+r)>>1;mrg(lson,ls[rt0]);mrg(rson,rs[rt0]);up(rt);
}
int que(int ps,int h,mat& c,int l,int r,int rt)
{
	int m=(l+r)>>1;
	if(l==r)
	{
		c=c*tr[rt];
		if(min(c.a[0][0],c.a[0][1])>=h)return 0;
		return sz[rt];
	}
	if(r<=ps)
	{
		auto t=c*tr[rs[rt]];
		if(min(t.a[0][0],t.a[0][1])<h){c=t;return que(ps,h,c,lson)+sz[rs[rt]];}
		return que(ps,h,c,rson);
	}
	if(ps<=m)return que(ps,h,c,lson);
	int ans=que(ps,h,c,rson);if(min(c.a[0][0],c.a[0][1])<h)ans+=que(ps,h,c,lson);
	return ans;
}
void sol(int u,int fa)
{
