using namespace std;
typedef long long ll;
const ll inf=1e18;
int n,m,s,e,nxt[20005],head[505],go[20005],fl[20005],k=1;
int cur[505],lvl[505];
int a[505],b[505],c[505];
ll ans;
void add(int u,int v,int w)
{
	nxt[++k]=head[u];
	head[u]=k;
	go[k]=v;
	fl[k]=w;
}
void Add(int u,int v,int w)
{
	// cerr<<u<<" "<<v<<" "<<w<<"\n";
	add(u,v,w);
	add(v,u,0);
}
bool bfs()
{
	queue<int> q;
	memcpy(cur,head,sizeof(head));
	memset(lvl,0x3f,sizeof(lvl));
	lvl[s]=0;
	q.emplace(s);
	while(!q.empty())
	{
		int x=q.front();
		q.pop();
		for(int i=head[x];i;i=nxt[i])
		{
			int g=go[i];
			if(!fl[i]) continue ;
			if(lvl[g]>lvl[x]+1)
			{
				lvl[g]=lvl[x]+1;
				q.emplace(g);
				if(g==e) return 1;
			}
		}
	}
	return 0;
}
ll dfs(int x,ll flow)
{
	if(x==e) return flow;
	ll res=0;
	for(int &i=cur[x];i;i=nxt[i])
	{
		int g=go[i];
		if(!fl[i]||lvl[g]!=lvl[x]+1) continue ;
		ll res1=dfs(g,min(flow,(ll)fl[i]));
		fl[i]-=res1;
		fl[i^1]+=res1;
		flow-=res1;
		res+=res1;
		if(!flow) return res;
	}
	return res;
}
int main()
{
