	{
		cin>>c[i];
	}
	for(int i=1;i<n;i++)
	{
		if(i==n-1) Add(i,e,a[i]+b[i+1]);
		else Add(i,e,a[i]);
		if(i==1) Add(s,i,c[i]+b[i]);
		else Add(s,i,c[i]);
		if(i+1<n) Add(i,i+1,b[i+1]),Add(i+1,i,b[i+1]);
	}
	for(int i=1;i<=m;i++)
	{
		int x,y,w;
		cin>>x>>y>>w;
		Add(x,y,w);
	}
	while(bfs()) ans+=dfs(s,inf);
