struct SuffixAutomaton{

    struct Node {
        int parent;
        int len;
        int occ;
        int isTerminal;
    };

    SuffixAutomaton() {}

    SuffixAutomaton(const std::vector<int>& tg){
        int n = int(tg.size());
        auto rtg = tg;
        std::reverse(rtg.begin(), rtg.end());
        auto sa = SuffixArray(rtg);
        auto lcp = LcpArray(rtg, sa);
        std::vector<int> isa(n);
        for(int i=0; i<n; i++) isa[sa[i]] = i;
        std::vector<int> sll(n+1, -1);
        std::vector<int> id(n+1, -1);
        std::vector<int> par(2, -1);
        std::vector<int> lenbuf(n*2, 0);
        std::vector<int> lencnt(n+1, 0);
        sufpos.assign(n+1, 0);
        id[0] = 0; par[1] = 0; sufpos[sa[0]] = 1;
        lenbuf[1] = n - sa[0];
        int cur = n - sa[0];
        auto PopCur = [&](){
            lenbuf[id[cur]] = cur;
            lencnt[cur]++;
            cur = sll[cur];
        };
        id[cur] = 1; sll[cur] = 0;
        for(int i=1; i<n; i++){
            int h = lcp[i-1];
            while(h <= sll[cur]) PopCur();
            if(h < cur){
                id[h] = int(par.size());
                par[id[cur]] = id[h];
                par.push_back(id[sll[cur]]);
                sll[h] = sll[cur];
                PopCur(); cur = h;
            }
            int q = n - sa[i];
            if(cur < q){
                id[q] = int(par.size());
                par.push_back(id[cur]);
                sll[q] = cur;
                cur = q;
            }
            sufpos[sa[i]] = id[cur];
        }

        while(cur >= 0) PopCur();
        int m = int(par.size());
        for(int i=0; i<n; i++) lencnt[i+1] += lencnt[i];
        std::vector<int> traversal(m);
        for(int i=0; i<m; i++) traversal[i] = --lencnt[lenbuf[i]];

        nodes.resize(m);
        for(auto& i : sufpos) i = traversal[i];
        for(int i=0; i<m; i++){
            if(i != 0) nodes[traversal[i]].parent = traversal[par[i]];
            nodes[traversal[i]].len = lenbuf[i];
        }
        nodes[0].parent = -1;
        std::vector<std::pair<int, std::pair<int,int>>> edgeBuf;
        for(int p=sufpos[0]; p>=0; p=nodes[p].parent){
            nodes[p].isTerminal = 1;
        }
        for(auto& i : sufpos) nodes[i].occ = 1;
        std::vector<int> vis(m);
        for(int i=0; i<n; i++){
            int u = sufpos[i];
            int v = sufpos[i+1];
            while(u > 0 && !vis[u]){
                vis[u] = 1;
                int up = nodes[u].parent;
                if(up == 0) edgeBuf.push_back({ 0, { rtg[i], u } });
                int h = up < 0 ? 0 : nodes[up].len;
                while(v > 0 && h < nodes[v].len + 1){
                    edgeBuf.push_back({ v, { rtg[i], u } });
                    v = nodes[v].parent;
                }
                u = up;
            }
        }
        link = CsrArray<std::pair<int,int>>::Construct(m, std::move(edgeBuf));
        for(int i=0; i<m; i++){
            std::sort(link[i].begin(), link[i].end());
        }
        for(int i=m-1; i>=1; i--){
            nodes[nodes[i].parent].occ += nodes[i].occ;
        }
    }

    int lengthOf(int v) const { return nodes[v].len; }
    int numNodes() const { return int(nodes.size()); }
    int next(int v, int nx_char) const {
        auto it = std::lower_bound(link[v].begin(), link[v].end(),
            std::make_pair(nx_char, -1));
        if(it == link[v].end() || it->first != nx_char) return -1;
        return it->second;
    }
    int nextWithFail(int v, int nx_char) const {
        do{
            int w = next(v, nx_char);
            if(w != -1) return w;
            v = nodes[v].parent;
        } while(v != 0);
        return 0;
    }
    int parentOf(int v) const { return nodes[v].parent; }
    auto operator[](int v) const { return link[v]; }
    bool isTerminal(int v) const { return nodes[v].isTerminal; }

    int edgeLength(int v) const {
        if(v == 0) return 0;
        return lengthOf(v) - lengthOf(parentOf(v));
    }

    std::vector<Node> nodes;
    CsrArray<std::pair<int, int>> link;
    std::vector<int> sufpos;

};

