namespace nachia {

struct LocationInSuffixTree{
    std::vector<int> w;
    std::vector<int> pp;
    std::vector<int> dfs;
    std::vector<int> idx;
    std::vector<int> sufs;
    LocationInSuffixTree() {}
    LocationInSuffixTree(const SuffixAutomaton& sa){
        int n = sa.numNodes();
        idx.resize(n);
        pp.assign(n, -1);
        dfs.resize(n, -1);
        w.assign(n, -1);
        std::vector<int> sz(n, 1);
        for(int i=n-1; i>=1; i--){
            idx[i] = sa.parentOf(i);
            sz[idx[i]] += sz[i];
            if(w[idx[i]] < 0 || sz[w[idx[i]]] < sz[i]){
                w[idx[i]] = i;
            }
        }
        idx[0] = -1;
        dfs[0] = 0;
        for(int i=0; i<n; i++){
            if(i == 0){ pp[0] = -1; }
            else if(dfs[i] < 0){
                dfs[i] = (idx[idx[i]] -= sz[i]);
                pp[dfs[i]] = ~dfs[idx[i]];
            }
            if(w[i] >= 0){
                int x = dfs[i];
                dfs[w[i]] = x + 1;
                pp[x+1] = pp[x] < 0 ? x : pp[x];
                idx[i] = x + sz[i];
            }
        }
        for(int i=0; i<n; i++) idx[dfs[i]] = i;
        for(int i=0; i<n; i++) w[i] = sa.lengthOf(idx[i]);
        sufs.resize(sa.sufpos.size());
        for(int i=0; i<int(sufs.size()); i++) sufs[i] = sa.sufpos[i];
    }
    int query(int l, int r) const {
        int len = r - l;
        int v = dfs[sufs[l]];
        while(v != 0 && pp[v] != 0){
            int x = pp[v] < 0 ? v : pp[v];
            if(len > w[~pp[x]]) break;
            v = ~pp[x];
        }
        if(pp[v] >= 0){
            v = (int)(std::lower_bound(
                w.begin() + pp[v], w.begin() + v + 1, len) - w.begin());
        }
        return idx[v];
    }
};

