struct Bass{

    struct Block {
        int len;
        int wi;
        int hi;
    };
    struct SubstrLocation {
        int bid;
        int x;
        int y;
    };
    int n;
    std::vector<Block> blocks;
    std::vector<int> w;
    std::vector<int> h;
    std::vector<int> trR;
    std::vector<int> trD;
    std::vector<int> rowToBlock;
    std::vector<int> colToBlock;
    std::vector<int> sufmap;
    std::vector<int> sufpos;
    LocationInSuffixTree loc;

    SubstrLocation locateBlock(int l, int r) const {
        int v = sufmap[loc.query(n-r, n-l)];
        SubstrLocation res;
        res.bid = rowToBlock[v];
        res.y = v - blocks[res.bid].wi;
        res.x = blocks[res.bid].len - (r-l) - res.y;
        return res;
    }

    Bass(){}
    Bass(std::vector<int> s){
        n = int(s.size());
        auto sufTree = SuffixAutomaton(s);
        loc = LocationInSuffixTree(sufTree);
        sufpos = std::move(sufTree.sufpos);
        int nrow = sufTree.numNodes();
        sufmap.assign(nrow, -1);
        rowToBlock.resize(nrow-1);
        w = h = std::vector<int>();
        std::vector<int> bottom(nrow);
        for(int v=1; v<nrow; v++) bottom[v] = v;
        for(int v=1; v<nrow; v++){
            if(sufTree[v].size() != 1) continue;
            if(sufTree.isTerminal(v)) continue;
            bottom[sufTree[v][0].second] = bottom[v];
            bottom[v] = -1;
        }
        for(int i=nrow-1; i>=1; i--) if(bottom[i] != -1){
            int v = bottom[i];
            Block b = { 0, int(w.size()), int(h.size()) };
            std::vector<int> sufs;
            while(true){
                sufs.push_back(v);
                if(v == i) break;
                v = sufTree[v][0].second;
            }
            b.len = sufTree.lengthOf(v);
            std::reverse(sufs.begin(), sufs.end());
            int bh = int(sufs.size());
            for(int y=0; y<bh; y++){
                w.push_back(sufTree.edgeLength(sufs[y]));
                sufmap[sufs[y]] = b.wi + y;
            }
            for(int y=bh-1; y>=0; y--){
                while((int)h.size() - b.hi < w[b.wi+y]){
                    h.push_back(y+1);
                }
            }
            blocks.push_back(b);
        }
        colToBlock.resize(h.size());
        for(int i=0; i<(int)blocks.size(); i++){
            int bh = h[blocks[i].hi];
            int bw = w[blocks[i].wi];
            for(int j=0; j<bh; j++) rowToBlock[blocks[i].wi + j] = i;
            for(int j=0; j<bw; j++) colToBlock[blocks[i].hi + j] = i;
        }
        trR.resize(w.size());
        for(int i=1; i<nrow; i++){
            trR[sufmap[i]] = sufmap[sufTree.parentOf(i)];
        }
        trD.resize(h.size(), -1);
        for(int v=1; v<nrow; v++) if(sufTree[v].size() != 1 || sufTree.isTerminal(v)){
            int bv = rowToBlock[sufmap[v]];
            int xst = blocks[bv].hi;
            for(auto [u,w] : sufTree[v]){
                int xst2 = blocks[rowToBlock[sufmap[w]]].hi;
                xst2 += sufTree.lengthOf(w) - sufTree.lengthOf(v) - 1;
                for(int x=0; x<width(bv); x++){
                    trD[xst2+x] = xst+x;
                }
            }
        }
        //for(auto x : w){ cout << x << " "; } cout << endl;
        //for(auto x : h){ cout << x << " "; } cout << endl;
        //for(auto x : sufmap){ cout << x << " "; } cout << endl;
        //for(auto x : toBlockIdx){ cout << x << " "; } cout << endl;
        //for(auto x : trR){ cout << x << " "; } cout << endl;
        //for(auto x : trD){ cout << x << " "; } cout << endl;
    }

    int numBlocks() const { return int(blocks.size()); }
    int sumHeight() const { return int(w.size()); }
    int sumWidth() const { return int(h.size()); }
    int height(int b) const { return h[blocks[b].hi]; }
    int width(int b) const { return w[blocks[b].wi]; }
    int rowStrLength(int r) const {
        int b = rowToBlock[r];
        return blocks[b].len - (r - blocks[b].wi);
    }
    int colStrLength(int c) const {
        int b = colToBlock[c];
        return blocks[b].len - (c - blocks[b].hi);
    }

    int rowDown(int r) const {
        if(rowStrLength(r) == 1) return -1;
        int b = rowToBlock[r];
        if(b == rowToBlock[r+1]) return r+1;
        return blocks[colToBlock[trD[blocks[b].hi]]].wi;
    }
    int colRight(int c) const {
        if(colStrLength(c) == 1) return -1;
        int b = colToBlock[c];
        if(b == colToBlock[c+1]) return c+1;
        return blocks[rowToBlock[trR[blocks[b].wi]]].hi;
    }

};

