int Popcount(unsigned long long c) noexcept {
#ifdef __GNUC__
    return __builtin_popcountll(c);
#else
    c = (c & (~0ull/3)) + ((c >> 1) & (~0ull/3));
    c = (c & (~0ull/5)) + ((c >> 2) & (~0ull/5));
    c = (c & (~0ull/17)) + ((c >> 4) & (~0ull/17));
    c = (c * (~0ull/257)) >> 56;
    return c;
#endif
}

// please ensure x != 0
int MsbIndex(unsigned long long x) noexcept {
#ifdef __GNUC__
    return 63 - __builtin_clzll(x);
#else
    using u64 = unsigned long long;
    int q = (x >> 32) ? 32 : 0;
    auto m = x >> q;
    constexpr u64 hi = 0x88888888;
    constexpr u64 mi = 0x11111111;
    m = (((m | ~(hi - (m & ~hi))) & hi) * mi) >> 35;
    m = (((m | ~(hi - (m & ~hi))) & hi) * mi) >> 31;
    q += (m & 0xf) << 2;
    q += 0x3333333322221100 >> (((x >> q) & 0xf) << 2) & 0xf;
    return q;
#endif
}

// please ensure x != 0
int LsbIndex(unsigned long long x) noexcept {
#ifdef __GNUC__
    return __builtin_ctzll(x);
#else
    return MsbIndex(x & -x);
#endif
}

}


namespace nachia{

template<class PosX, class PosY>
struct TwoDRectangleQuery{
private:

struct BitVectorRank {
    using u64 = std::uint64_t;
    using u32 = std::uint32_t;
    
    std::vector<std::pair<u64, u32>> a;
    BitVectorRank(const std::vector<bool>& b = {}){
        int n = b.size();
        a.assign(n/64 + 1, std::make_pair((u64)0, (u32)0));
        auto p = b.begin();
        u32 sum = 0;
        u64 tmp = 0;
        for(int i=0; i<=n; i+=64){
            tmp = 0;
            int maxd = std::min<int>(n - i, 64);
            for(int d=0; d<maxd; d++){
                tmp |= (u64)(*p ? 1 : 0) << d;
                ++p;
            }
            a[i/64] = std::make_pair(tmp, sum);
            sum += Popcount(tmp);
        }
    }
    std::uint32_t rank(std::uint32_t i) const {
        auto [b, s] = a[i >> 6];
        return (u32)(Popcount(b & ~(~u64(0) << (i & 63)))) + s;
    }
    bool get(std::uint32_t i) const { return (a[i >> 6].first >> (i & 63)) & 1; }
};
    
    int n;
    int N;
    int logN;
    std::vector<PosX> Xsorted;
    std::vector<PosY> Ysorted;
    std::vector<int> rankX;
    std::vector<std::vector<int>> Idx;
    std::vector<int> Z;
    std::vector<BitVectorRank> L;

public:

    TwoDRectangleQuery(){}

    TwoDRectangleQuery(const std::vector<std::pair<PosX, PosY>>& pos){
        n = pos.size();

        std::vector<int> sortIY(n);
        for(int i=0; i<n; i++) sortIY[i] = i;
        std::sort(sortIY.begin(),sortIY.end(),[&pos](int l,int r){ return pos[l].second<pos[r].second; });
        Ysorted.resize(n);
        for(int i=0; i<n; i++) Ysorted[i] = pos[sortIY[i]].second;

        std::vector<int> sortIX(n);
        rankX.resize(n);
        for(int i=0; i<n; i++) sortIX[i] = i;
        std::sort(sortIX.begin(),sortIX.end(),[&pos](int l,int r){ return pos[l]<pos[r]; });
        Xsorted.resize(n);
        for(int i=0; i<n; i++) Xsorted[i] = pos[sortIX[i]].first;
        for(int i=0; i<n; i++) rankX[sortIX[i]] = i;

        N = 1; logN = 0;
        while(N < n){ N *= 2; logN++; }
        Idx.assign(logN+1, std::vector<int>(n,-1));
        L.resize(logN);
        Z.resize(logN);
        for(int i=0; i<n; i++) Idx.back()[i] = sortIY[i];
        for(int i=logN-1; i>=0; i--){
            std::vector<bool> Lbuf(n,0);
            auto& preList = Idx[i+1];
            int z = ((n >> (i+1)) << i) + std::min(1<<i, (n % (2 << i)));
            Z[i] = z;
            int ai = 0, bi = z;
            for(int k=0; k<n; k++){
                bool chooseb = rankX[preList[k]] & (1<<i);
                if(!chooseb) Idx[i][ai++] = preList[k];
                else Idx[i][bi++] = preList[k];
                Lbuf[k] = !chooseb;
            }
            L[i] = BitVectorRank(Lbuf);
        }

        for(int i=0; i<n; i++) rankX[sortIY[i]] = i;
    }
 
    int getSegmentCount() const { return Idx.size(); }
    int size() const { return n; }
    int toVtx(int d, int i) const { return Idx[d][i]; }


    struct UpdatePoint{ int d, i; };

    std::vector<UpdatePoint> getUpdatePoints(int v) const {
        std::vector<UpdatePoint> res(logN+1);
        int p = rankX[v];
        int d = logN;
        while(d > 0){
            res[d] = { d,p };
            d--;
            if(L[d].get(p)) p = L[d].rank(p);
            else p = Z[d] + p - L[d].rank(p);
        }
        res[d] = {d,p};
        return res;
    }


    struct Query{ int d,l,r; };
    std::vector<Query> getRangesFromIdx(int xl, int xr, int yl, int yr) const {
        if(xl >= xr || yl >= yr) return {};
        std::vector<Query> res;
        struct Search{ int i, xa, xb, ys, yt; };
        std::vector<Search> Q;
        res.reserve((logN+1)*2);
        Q.reserve((logN+1)*2);
        Q.push_back({ logN,0,n,yl,yr });
        for(int i=0; i<(int)Q.size(); i++){
            auto p = Q[i];
            if(p.xa == p.xb) continue;
            if(xl <= p.xa && p.xb <= xr){
                res.push_back({ p.i, p.ys, p.yt });
                continue;
            }
            p.i--;
            int nxs = L[p.i].rank(p.ys), nxt = L[p.i].rank(p.yt);
            int xm = p.xa+(1<<p.i);
            if(xl < xm) Q.push_back({ p.i,p.xa,xm,nxs,nxt });
            if(xm < xr) Q.push_back({ p.i,xm,p.xb,Z[p.i]+p.ys-nxs,Z[p.i]+p.yt-nxt });
        }
        return res; 
    }
  
    std::vector<Query> getRanges(PosX xl, PosX xr, PosY yl, PosY yr) const {
        return getRangesFromIdx(
            lower_bound(Xsorted.begin(),Xsorted.end(),xl) - Xsorted.begin(),
            lower_bound(Xsorted.begin(),Xsorted.end(),xr) - Xsorted.begin(),
            lower_bound(Ysorted.begin(),Ysorted.end(),yl) - Ysorted.begin(),
            lower_bound(Ysorted.begin(),Ysorted.end(),yr) - Ysorted.begin()
        );
    }
};

} // namespace nachia

namespace nachia {

struct PathToRootUpdateTrace{
    struct Elem {
        int v;
        int x;
    };
    struct Node {
        int p;
        int l;
        int r;
        int x;
    };
    std::vector<Node> a;
    PathToRootUpdateTrace(){}
    PathToRootUpdateTrace(
        std::vector<int> parent,
        std::vector<int> label
    ){
        int n = parent.size();
        a.resize(n);
        for(int i=0; i<n; i++){
            a[i].p = parent[i];
            a[i].x = label[i];
            a[i].l = a[i].r = -1;
        }
    }
    void setParentChild(int v, int c){
        int p = a[v].p;
        if(p < 0) return;
        if(a[p].l == v) a[p].l = c;
        if(a[p].r == v) a[p].r = c;
    }
    void rotL(int v) {
        int p = a[v].p;
        int l = a[v].l;
        a[v].x = a[p].x;
        setParentChild(p, v);
        a[v].p = a[p].p;
        a[p].p = v;
        a[p].r = l;
        if(l >= 0) a[l].p = p;
        a[v].l = p;
    }
    void rotR(int v) {
        int p = a[v].p;
        int r = a[v].r;
        a[v].x = a[p].x;
        setParentChild(p, v);
        a[v].p = a[p].p;
        a[p].p = v;
        a[p].l = r;
        if(r >= 0) a[r].p = p;
        a[v].r = p;
    }
    void splay(int c) {
        while(true) {
            int p = a[c].p;
            if(p < 0) break;
            int pp = a[p].p;
            if(a[p].l == c){
                if(pp < 0){ rotR(c); }
                else if(a[pp].l == p){ rotR(p); rotR(c); }
                else if(a[pp].r == p){ rotR(c); rotL(c); }
                else{ rotR(c); }
            }
            else if(a[p].r == c){
                if(pp < 0){ rotL(c); }
                else if(a[pp].r == p){ rotL(p); rotL(c); }
                else if(a[pp].l == p){ rotL(c); rotR(c); }
                else{ rotL(c); }
            }
            else break;
        }
    }
    std::vector<Elem> expose(int c, int x) {
        std::vector<Elem> res;
        auto p = c;
        while(p >= 0){
            splay(p);
            res.push_back({ p, a[p].x });
            p = a[p].p;
        }
        p = c;
        while(true){
            if(a[p].r >= 0) a[a[p].r].x = a[p].x;
            if(a[p].p < 0) break;
            a[a[p].p].r = p; p = a[p].p;
        }
        splay(c);
        a[c].r = -1; a[c].x = x;
        return res;
    }
};

} // namespace nachia

namespace nachia{

struct FindIndependentPrefix{
    FindIndependentPrefix(){}
    FindIndependentPrefix(
        const Bass& bass
    ){
        int n = bass.n;
        int m = bass.sumHeight();
        std::vector<int> par(m+1, -1);
        for(int i=0; i<m; i++){
            par[i] = bass.trR[i];
            if(par[i] < 0) par[i] = m;
        }
        PathToRootUpdateTrace pathUpd(par, std::vector<int>(m+1, -1));
        std::vector<int> vpre(n+1);
        vpre[n] = 0;
        for(int i=n-1; i>=1; i--) vpre[i] = bass.rowDown(vpre[i+1]);
        posSep.resize(n+1);
        for(int r=1; r<=n; r++){
            int v = vpre[r];
            auto buf = pathUpd.expose(v, r);
            for(auto [v,x] : buf){
                if(v == m) continue;
                posDet.push_back({ bass.rowStrLength(v), x });
            }
            posSep[r] = (int)posDet.size();
        }
    }

    int determinePos(int l, int r){
        if(l >= r) return -1;
        // ok : double occurrence of full length
        int ng = posSep[r-1]-1, ok = posSep[r];
        while(ng + 1 < ok){
            int x = ng + (ok - ng) / 2;
            if(l <= posDet[x].pos - posDet[x].len) ok = x;
            else ng = x;
        }
        int pos = r;
        if(ng != posSep[r-1] - 1){
            int pos1 = r - (posDet[ng].pos - l);
            if(pos > pos1) pos = pos1;
        }
        if(ok != posSep[r]){
            int pos1 = r - posDet[ok].len;
            if(pos > pos1) pos = pos1;
        }
        return pos;
    }

    struct SuffixMatch {
        int len;
        int pos;
    };
    
    std::vector<SuffixMatch> posDet;
    std::vector<int> posSep;
};

