namespace nachia{

struct RangeCountOccurrenceOfSubstrings{
    RangeCountOccurrenceOfSubstrings(){}
    RangeCountOccurrenceOfSubstrings(
        std::vector<int> src,
        std::vector<std::pair<int,int>> dict
    ) : m_bass(src) {
        m_sum1.resize(m_bass.sumWidth() + 1);
        m_sumRow.resize(m_bass.sumHeight());
        m_sumCol.resize(m_bass.sumWidth());
        std::vector<std::pair<int,int>> pos;
        for(auto [l,r] : dict){
            auto [b,x,y] = m_bass.locateBlock(l, r);
            int gy = m_bass.blocks[b].wi + y;
            int gx = m_bass.blocks[b].hi + x;
            m_sumRow[gy] += 1;
            m_sumCol[gx] += 1;
            pos.push_back({ gx, gy });
        }
        m_2d = TwoDRectangleQuery<int,int>(pos);
        for(int i=m_bass.sumHeight()-1; i>=0; i--){
            int j = m_bass.trR[i];
            if(j < 0) continue;
            m_sumRow[i] += m_sumRow[j];
        }
        for(int i=m_bass.sumHeight()-1; i>=0; i--){
            int j = m_bass.rowDown(i);
            if(j < 0) continue;
            m_sumRow[i] += m_sumRow[j];
        }
        for(int i=m_bass.sumWidth()-1; i>=0; i--){
            int j = m_bass.trD[i];
            if(j < 0) continue;
            m_sumCol[i] += m_sumCol[j];
        }
        for(int i=m_bass.sumWidth()-1; i>=0; i--){
            int j = m_bass.trD[i];
            if(j < 0) continue;
            m_sum1[i] = m_sumCol[j];
        }
        for(int i=m_bass.sumWidth()-1; i>=0; i--){
            m_sum1[i] += m_sum1[i+1];
        }
    }

    long long count(int l, int r) const {
        if(l >= r) return 0;
        auto [b,x,y] = m_bass.locateBlock(l, r);
        int gy = m_bass.blocks[b].wi + y;
        int gx = m_bass.blocks[b].hi + x;
        int ry = m_bass.blocks[b].wi + m_bass.h[gx];
        int rx = m_bass.blocks[b].hi + m_bass.w[gy];
        long long ans = 0;
        for(auto [d,xl,xr] : m_2d.getRanges(gx, rx, gy, ry)) ans += xr-xl;
        ans += m_sum1[gx] - m_sum1[rx];
        if(m_bass.trR[gy] >= 0) ans += m_sumRow[m_bass.trR[gy]];
        return ans;
    }

    void prepareForDistinctCount(){
        int n = m_bass.n;

        m_findPos = FindIndependentPrefix(m_bass);

        int m = m_bass.sumWidth();
        std::vector<int> par(m+1, -1);
        for(int i=0; i<m; i++){
            par[i] = m_bass.trD[i];
            if(par[i] < 0) par[i] = m;
        }
        std::vector<int> vpre(n+1);
        vpre[0] = 0;
        for(int i=1; i<=n; i++) vpre[i] = m_bass.colRight(vpre[i-1]);
        auto pathUpd = PathToRootUpdateTrace(par, std::vector<int>(m+1, n));
        std::vector<int> A2Sep(n+1, 0);
        std::vector<AddQuery> A2Buf;
        for(int l=n-1; l>=0; l--){
            int v = vpre[l];
            auto buf = pathUpd.expose(v, l);
            //for(auto [v,x] : buf){ cout << "(" << v << "," << x << ")"; } cout << endl;
            for(int i=0; i+1<int(buf.size()); i++){
                if(buf[i+1].v == m) continue;
                int len = m_bass.colStrLength(buf[i+1].v) + 1;
                int lofr = buf[i+1].x + len;
                int rofr = buf[i].x + len;
                if(n < lofr) continue;
                if(n+1 < rofr) rofr = n+1;
                A2Buf.push_back({ lofr, rofr, m_sumCol[buf[i+1].v] });
            }
            A2Sep[l] = int(A2Buf.size());
        }
        std::reverse(A2Buf.begin(), A2Buf.end());
        for(auto& p : A2Sep) p = int(A2Buf.size()) - p;
        A2Query = CsrArray<AddQuery>::FromRaw(std::move(A2Buf), std::move(A2Sep));
    }
    
    struct SuffixMatch {
        int len;
        int pos;
    };

    struct AddQuery {
        int l;
        int r;
        long long w;
    };
    
    Bass m_bass;
    std::vector<long long> m_sum1;
    std::vector<long long> m_sumRow;
    TwoDRectangleQuery<int,int> m_2d;

    FindIndependentPrefix m_findPos;
    std::vector<long long> m_sumCol;
    
    CsrArray<AddQuery> A2Query;
};

