#include <bits/stdc++.h>

using namespace std;

typedef pair<int, int> PII;

const int N = 2e6 + 5;
const int INF = 0x3f3f3f3f;

int n, m, k;
char s[N];

struct Segment{
	int l, r, c;
}x[N];

struct Node{
	int ls, rs, siz;
	Segment vl, vr;
	int s;
	int tag;
	PII mp[2];
}t[N * 4];
int pid, sta[N * 4], tt;

struct Interval{
	int l, r, rt, cl, cr;
}rt;

#define LS t[u].ls
#define RS t[u].rs

inline void PushUp(int u)
{
	t[u].siz = t[LS].siz + t[RS].siz;
	t[u].vl = t[LS].vl, t[u].vr = t[RS].vr;
	t[u].mp[0] = min(t[LS].mp[0], t[RS].mp[0]);
	t[u].mp[1] = min(t[LS].mp[1], t[RS].mp[1]);
	if(t[LS].vr.c == 1 && t[RS].vl.c == 0) t[u].mp[0] = min(t[u].mp[0], make_pair((t[RS].vl.l - t[LS].vr.r - 1) / 2, t[LS].vr.r));
	if(t[LS].vr.c == 0 && t[RS].vl.c == 1) t[u].mp[1] = min(t[u].mp[1], make_pair((t[RS].vl.l - t[LS].vr.r - 1) / 2, t[LS].vr.r));
	t[u].s = t[LS].s + t[RS].s + (t[RS].vl.l - t[LS].vr.r - 1 + !t[LS].vr.c) / 2;
}
inline void Change(int u, int d)
{
	int l0 = t[u].vr.r - t[u].vl.l;
	t[u].vl.l += d * (t[u].vl.c ? 1 : -1);
	t[u].vl.r += d * (t[u].vl.c ? 1 : -1);
	t[u].vr.l += d * (t[u].vr.c ? 1 : -1);
	t[u].vr.r += d * (t[u].vr.c ? 1 : -1);
	int l1 = t[u].vr.r - t[u].vl.l;
	t[u].s += (l1 - l0) / 2;
	t[u].mp[0].first -= d;
	t[u].mp[1].first += d;
	t[u].mp[0].second += d;
	t[u].mp[1].second -= d;
	t[u].tag += d;
}
inline void PushDown(int u)
{
	if(t[u].tag)
	{
		Change(LS, t[u].tag);
		Change(RS, t[u].tag);
		t[u].tag = 0;
	}
}
inline int NewNode()
{
	int u = tt ? sta[tt -- ] : ++ pid;
	t[u].ls = t[u].rs = t[u].tag = 0;
	return u;
}
inline int NewNode(Segment v)
{
	int u = tt ? sta[tt -- ] : ++ pid;
	t[u].ls = t[u].rs = t[u].tag = 0;
	t[u].vl = t[u].vr = v;
	t[u].mp[0].first = t[u].mp[1].first = INF;
	t[u].s = (v.r - v.l + 1) * v.c;
	return u;
}
inline int MergeNode(int u, int v)
{
	int w = NewNode();
	t[w].ls = u, t[w].rs = v;
	PushUp(w);
	return w;
}
inline int Merge(int u, int v)
{
	if(!u || !v) return u | v;
	int lim = (t[u].siz + t[v].siz) >> 2;
	if(min(t[u].siz, t[v].siz) >= lim) return MergeNode(u, v);
	if(t[u].siz > t[v].siz)
	{
		PushDown(u), sta[ ++ tt] = u;
		int p = t[u].ls, q = t[u].rs;
		if(t[p].siz >= lim)
		{
			return Merge(p, Merge(q, v));
		}
		else
		{
			PushDown(q), sta[ ++ tt] = q;
			int x = t[q].ls, y = t[q].rs;
			return Merge(Merge(p, x), Merge(y, v));
		}
	}
	else
	{
		PushDown(v), sta[ ++ tt] = v;
		int p = t[v].rs, q = t[v].ls;
		if(t[p].siz >= lim)
		{
			return Merge(Merge(u, q), p);
		}
		else
		{
			PushDown(q), sta[ ++ tt] = q;
			int x = t[q].ls, y = t[q].rs;
			return Merge(Merge(u, x), Merge(y, p));
		}
	}
}
inline int Build(int a, int b)
{
	if(a == b)
	{
		return NewNode(x[a]);
	}
	else
	{
		int mid = (a + b) >> 1;
		return MergeNode(Build(a, mid), Build(mid + 1, b));
	}
}
inline void Split(int u, int k, int &L, int &R)
{
	if(t[u].vr.r <= k) return L = u, R = 0, void();
	if(t[u].vl.l >  k) return L = 0, R = u, void();
	if(!t[u].ls)
	{
		L = k > t[u].vl.l ? NewNode({t[u].vl.l, k, t[u].vl.c}) : 0;
		R = k + 1 < t[u].vl.r ? NewNode({k + 1, t[u].vl.r, t[u].vl.c}) : 0;
		sta[ ++ tt] = u;
		return ;
	}
	PushDown(u);
	if(t[LS].vr.r <= k)
	{
		Split(RS, k, L, R);
		L = Merge(LS, L);
	}
	else
	{
		Split(LS, k, L, R);
		R = Merge(R, RS);
	}
	sta[ ++ tt] = u;
}
inline void FindL(int u, int d)
{
	for(; LS; u = LS)
	{
		PushDown(u);
		t[u].s += (t[u].vl.l - d) * t[u].vl.c;
		t[u].vl.l = d;
	}
	t[u].s += (t[u].vl.l - d) * t[u].vl.c;
	t[u].vl.l = t[u].vr.l = d;
}
inline void FindR(int u, int d)
{
	for(; RS; u = RS)
	{
		PushDown(u);
		t[u].s += (d - t[u].vr.r) * t[u].vr.c;
		t[u].vr.r = d;
	}
	t[u].s += (d - t[u].vr.r) * t[u].vr.c;
	t[u].vr.r = t[u].vl.r = d;
}
inline void DeleteR(int &u, int k)
{
	if(t[u].ls == t[u].rs)
	{
		t[u].vl.r -- ;
		t[u].vr.r -- ;
		t[u].s -= t[u].vl.c;
		if(t[u].vl.l >= t[u].vr.r)
		{
			sta[ ++ tt] = u;
			u = 0;
		}
		return ;
	}
	PushDown(u);
	if(t[t[u].rs].vl.r <= k) DeleteR(t[u].rs, k);
	else DeleteR(t[u].ls, k);
	sta[ ++ tt] = u;
	u = Merge(t[u].ls, t[u].rs);
}
inline void DeleteL(int &u, int k)
{
	if(t[u].ls == t[u].rs)
	{
		t[u].vl.l ++ ;
		t[u].vr.l ++ ;
		t[u].s -= t[u].vr.c;
		if(t[u].vl.l >= t[u].vr.r)
		{
			sta[ ++ tt] = u;
			u = 0;
		}
		return ;
	}
	PushDown(u);
	if(t[t[u].ls].vr.l > k) DeleteL(t[u].ls, k);
	else DeleteL(t[u].rs, k);
	sta[ ++ tt] = u;
	u = Merge(t[u].ls, t[u].rs);
}

inline void Merge(Interval &u, Interval L, Interval R)
{
	u.l = L.l, u.r = R.r;
	u.cl = L.cl, u.cr = R.cr;
	if(L.cr == R.cl)
	{
		if(L.rt && t[L.rt].vr.r == L.r && R.rt && t[R.rt].vl.l == R.l)
		{
			FindR(L.rt, t[R.rt].vl.r);
			int T;
			Split(R.rt, t[L.rt].vr.r, T, R.rt);
		}
		else if(L.rt && t[L.rt].vr.r == L.r)
		{
			FindR(L.rt, t[L.rt].vr.r + 1);
		}
		else if(R.rt && t[R.rt].vl.l == R.l)
		{
			FindL(R.rt, t[R.rt].vl.l - 1);
		}
		else
		{
			L.rt = Merge(L.rt, NewNode({L.r, R.l, L.cr}));
		}
	}
	u.rt = Merge(L.rt, R.rt);
}
inline void Split(Interval u, int k, Interval &L, Interval &R)
{
	L.l = u.l, L.r = k;
	R.l = k + 1, R.r = u.r;
	Split(u.rt, k, L.rt, R.rt);
	L.cl = u.cl;
	L.cr = ((L.rt ? t[L.rt].vr.c ^ t[L.rt].vr.r : L.cl ^ L.l) ^ L.r) & 1;
	R.cr = u.cr;
	R.cl = ((R.rt ? t[R.rt].vl.c ^ t[R.rt].vl.l : R.cr ^ R.r) ^ R.l) & 1;
}
inline int Calc(Interval u)
{
	if(u.rt)
	{
		return t[u.rt].s + (t[u.rt].vl.l - u.l + u.cl) / 2 + (u.r - t[u.rt].vr.r + u.cr) / 2;
	}
	else
	{
		return (u.r - u.l + 1 + u.cl) / 2;
	}
}

inline void Modify(int l, int r, int d)
{
	if(l == r) return ;
	Interval L, U, R;
	Split(rt, l - 1, L, U);
	Split(U, r, U, R);

	Interval LD, RD;
	LD.l = RD.l = -1;
	do{
		if(LD.l != -1) Merge(L, L, LD);
		if(U.l > U.r)
		{
			Merge(rt, L, R);
			return ;
		}
		Split(U, U.rt && t[U.rt].vl.l == l ? t[U.rt].vl.r : U.l, LD, U);
	}while(LD.cr != d);
	do{
		if(RD.l != -1) Merge(R, RD, R);
		if(U.l > U.r)
		{
			Merge(L, L, LD);
			Merge(rt, L, R);
			return ;
		}
		Split(U, U.rt && t[U.rt].vr.r == r ? t[U.rt].vr.l - 1 : U.r - 1, U, RD);
	}while(RD.cl != !d);

	if(LD.cr == d)
	{
		U.l -- , U.cl ^= 1;
		LD.r -- ;
		if(LD.rt && t[LD.rt].vr.r == LD.r + 1)
		{
			DeleteR(LD.rt, t[LD.rt].vr.r);
		}
	}
	if(RD.cl == !d)
	{
		U.r ++ , U.cr ^= 1;
		RD.l ++ ;
		if(RD.rt && t[RD.rt].vl.l == RD.l - 1)
		{
			DeleteL(RD.rt, t[RD.rt].vl.l - 1);
		}
	}

	while(t[U.rt].mp[d].first <= 0)
	{
		int x = t[U.rt].mp[d].second;
		DeleteR(U.rt, x);
		DeleteL(U.rt, x);
	}

	if(U.rt)
	{
		Change(U.rt, d ? -1 : 1);
		U.cl = (t[U.rt].vl.l ^ t[U.rt].vl.c ^ U.l) & 1;
		U.cr = (t[U.rt].vr.r ^ t[U.rt].vr.c ^ U.r) & 1;
	}
	else
	{
		U.cl ^= 1, U.cr ^= 1;
	}

	if(LD.l <= LD.r) Merge(U, LD, U);
	if(RD.l <= RD.r) Merge(U, U, RD);
	if(L.l <= L.r) Merge(U, L, U);
	if(R.l <= R.r) Merge(U, U, R);
	rt = U;
}
inline int Query(int l, int r)
{
	Interval L, U, R;
	Split(rt, l - 1, L, U);
	Split(U, r, U, R);
	int res = Calc(U);
	if(L.l <= L.r) Merge(U, L, U);
	if(R.l <= R.r) Merge(U, U, R);
	rt = U;
	return res;
}

int main()
{
	t[0].mp[0].first = t[0].mp[1].first = INF;
	scanf("%d%d%s", &n, &m, s + 1);
	for(int i = 1; i <= n; i ++ )
	{
		int j = i;
		while(s[i] == s[j + 1]) j ++ ;
