const int p=998244353,y=3,ny=(p+1)/3;
const int N=7e5+10;
int n,m;
int fac[N],h[N],f[N],dp[N];
int mo(int x){
	return x>=p?x-p:x;
}
void add(int &x,int y) {x=mo(x+y);}
int a[N],b[N],r[N],limit,l;
int ksm(int a,int b=p-2){
	int ans=1;
	for(;b;b>>=1,a=a*a%p) if(b&1) ans=ans*a%p;
	return ans;
}
void NTT(int *a,int len,int tp){
	for(int i=0;i<len;i++) if(i<r[i]) swap(a[i],a[r[i]]);
	for(int mid=1;mid<len;mid<<=1){
		int wn=ksm((tp?y:ny),(p-1)/(mid<<1));
		for(int j=0,R=mid<<1;j<len;j+=R){
			for(int k=0,w=1;k<mid;k++,w=w*wn%p){
				int x=a[j+k],y=a[j+k+mid]*w%p;
				a[j+k]=mo(x+y);
				a[j+k+mid]=mo(x-y+p);
			}
		}
	}
	if(tp) return;
	int inv=ksm(len);
	for(int i=0;i<len;i++) a[i]=a[i]*inv%p;
}
void mul(int *a,int *b,int l1,int l2){
	for(limit=1,l=0;limit<=l1+l2;limit<<=1,l++);
	for(int i=0;i<limit;i++) r[i]=(r[i>>1]>>1)|((i&1)<<(l-1));
	for(int i=l1;i<=limit;i++) a[i]=0;
	for(int i=l2;i<=limit;i++) b[i]=0;
	NTT(a,limit,1),NTT(b,limit,1);
	for(int i=0;i<limit;i++) a[i]=a[i]*b[i]%p;
	NTT(a,limit,0);
}
void calc_f(int l,int r){
	if(l==r) {f[l]=mo(fac[l]-f[l]+p);return;}
	int mid=l+r>>1;
	calc_f(l,mid);
	for(int i=l;i<=mid;i++) a[i-l]=f[i];
	for(int i=0;i<=r-l;i++) b[i]=fac[i];
	mul(a,b,mid-l+1,r-l+1);
	for(int i=mid+1;i<=r;i++) add(f[i],a[i-l]);
	calc_f(mid+1,r);
}
void calc_dp(int l,int r){
	if(l==r) {
		dp[l]=mo(dp[l]+f[l])*ksm(mo(fac[l]-f[l]+p))%p;
		if(l==1) dp[l]=-1;
		return;
	}
	int mid=l+r>>1;
	calc_dp(l,mid);
	for(int i=l;i<=mid;i++) a[i-l]=(dp[i]+1)*f[i]%p;
	for(int i=0;i<=r-l;i++) b[i]=h[i];
	mul(a,b,mid-l+1,r-l+1);
	for(int i=mid+1;i<=r;i++) add(dp[i],a[i-l]);
	calc_dp(mid+1,r);
}
