using Iter=set<Q>::iterator;
inline Iter get(int x)
{
	Iter it=s.lower_bound({x,0,0});
	if(it!=s.end()&&x==it->l)return it;
	it--;Q p={it->l,x-1,it->id},q={x,it->r,it->id};
	s.erase(it);s.insert(p);return s.insert(q).first;
}

inline void ins(int l,int r,int v,bool o)
{
	Iter R=get(r+1),L=get(l);
	if(o)f[0][v]=L->id;
	s.erase(L,R);
	s.insert(Q{l,r,v});
}

