inline void upd(int u)
{
	c[u]^=1;
	if(c[u])
	{
		if(A.gsum(dfn[u],mxn[u])==0)
			B.upd(d[find(u)]+1,1),B.upd(d[u]+1,-1);
		Cnt++,A.upd(dfn[u], 1);
	}
	else
	{
		Cnt--,A.upd(dfn[u],-1);
		if(A.gsum(dfn[u],mxn[u])==0)
			B.upd(d[find(u)]+1,-1),B.upd(d[u]+1,1);
	}
