		if(j*2-cntr>=0){
			int i=j*2-cntr;
			if(i+1<=cntl-mnh[j]*2) bannum[i]++,bannum[i+1]--;
		}
		int L=max(0,j*2-cntr),R=min(j,cntl-mnh[j]*2);
		if(L<=R){
