	inline int qpow(int x,int y){
		int res=1;
		while(y){
			if(y&1) res=1ll*res*x%mod;
			x=1ll*x*x%mod;
			y>>=1;
		}
		return res;
	}
	inline void Prefix(int T,int L=0){
		int l=log2(T*2-1),t=1<<l;
		g0[1]=g0[t]=1,g0[t+1]=qpow(R,mod>>(l+1));
		for(int i=2;i<=2*t;i++) g0[t+i]=1ll*g0[t+i-1]*g0[t+1]%mod;
		for(int i=t-1;i>=1;i--) g0[i]=g0[2*i];
		fac[0]=1;
		for(int i=1;i<=L;i++)
			fac[i]=1ll*fac[i-1]*i%mod;
		ifac[L]=qpow(fac[L],mod-2);
		for(int i=L;i>=1;i--)
			ifac[i-1]=1ll*ifac[i]*i%mod;
		for(int i=1;i<=L;i++)
			inv_[i]=1ll*fac[i-1]*ifac[i]%mod;
	}
	inline int add(int a,int b){
		return a+b>=mod?a+b-mod:a+b;
	}
	inline int dec(int a,int b){
		return a>=b?a-b:a+mod-b;
	}
