					b[j+k]=t1+t2,b[i+j+k]=t1+mod-t2;
				}
			}
		}
		for(int i=0;i<lim;i++)
			a[i]=b[i]%mod;
		if(T==1) return ;
		int Inv= qpow(lim,mod-2);
		for(int i=0;i<lim;i++)
