	inline Poly Exp(const Poly &a){
		Poly F,G;
		int n=a.size();
		if(n==1) return {1};
		F=a,F.resize(n+1>>1);
		G=Exp(F);
		init_(n<<1);
		F=a,G.resize(n);
		Poly H=F-Ln(G);
		H[0]=add(H[0],1);
		G=G*H;
		G.resize(n);
		return G;
	}
	inline Poly Sqrt(const Poly &a){
		Poly F,G;
		int n=a.size();
		if(n==1) return {1};
		F=a,F.resize(n+1>>1);
		G=Sqrt(F);
		init_(n<<1);
		F=a,G.resize(n);
		G=(G+F*Inv(G))*((mod+1)/2);
		G.resize(n);
