poly comp(poly f,poly g){
	int n=f.size(),m=g.size();
	Poly a(n),b(m);
	For(i,0,n-1)a[i]=f[i].x;
	For(i,0,m-1)b[i]=g[i].x;
	a=Comp(a,b);
	For(i,0,n-1)f[i].x=a[i];
	return f;
}

