	LPSolver(const vvd& A,const vd& b,const vd &c):m(sz(b)),n(sz(c)),N(n+1),B(m),D(m+2,vd(n+2)){
		rep(i,0,m)rep(j,0,n)D[i][j]=A[i][j];
