            auto rayIntersect = rayCircleIntersect(T.front(), w, s) || rayCircleIntersect(T.back(), w, s);
            auto inAngle = pointInAngle(T.front(), T.back(), w);
 
            if(!rayIntersect && !inAngle){
                cout<<-1<<'\n';
                continue;
            }
 
            if(orient({0, 0}, T.front(), w) >= 0){
                Tf v = touchCirlce(T.front(), w, s);
                if(v != -1){
                    cout<<fixed<<setprecision(10)<<T.front().len() / v<<'\n';
                    continue;
                }
            }
 
            if(orient({0, 0}, T.back(), w) <= 0){
                Tf v = touchCirlce(T.back(), w, s);
                if(v != -1){
                    cout<<fixed<<setprecision(10)<<T.back().len() / v<<'\n';
                    continue;
                }
            }
 
            int crossingSeg = -1;
            if(inAngle){
                crossingSeg = getCrossingIndex(T, w);
            }
 
            const Tf START = 2e9;
 
            Tf delta = START;
            Tf ans = START;
 
            for(int i = 0; i<55; i++){
                delta /= 2;
                auto t = ans - delta;
                auto wt = w * t;
                auto rt = s * t;
 
                if(crossingSeg != -1 && orient(T[crossingSeg], T[crossingSeg+1], wt) >= 0){
                    ans = t;
                    continue;
                }
 
                if(acrossRay(T.front(), wt)){
                    auto d = perpDistance(T.front(), wt);
                    if(dcmp(d - rt) <= 0){
                        ans = t;
                        continue;
                    }
                }
 
                if(acrossRay(T.back(), wt)){
                    auto d = perpDistance(T.back(), wt);
                    if(dcmp(d - rt) <= 0){
                        ans = t;
                        continue;
                    }
 
                }
 
                auto d = getPolylineDistance(T, wt);
                if(dcmp(d-rt) <= 0){
                    ans = t;
                    continue;
                }
            }
 
            cout<<fixed<<setprecision(10)<<ans<<'\n';
        }
    }
}
 
