}t[N],I;
void pushup(int rt){
	t[rt].sum=t[t[rt].ch[0]].sum^t[t[rt].ch[1]].sum^t[rt].val;
    for(int c:{0,1}){
        t[rt].tl[c]=t[rt].tr[c]=0;
    }
    for(int c:{0,1}){
        t[rt].tl[c]+=t[t[rt].ch[0]].tl[c];
        t[rt].tl[c]+=t[t[rt].ch[1]].tl[c^t[t[rt].ch[0]].sum^t[rt].val];
        t[rt].tr[c]+=t[t[rt].ch[1]].tr[c];
        t[rt].tr[c]+=t[t[rt].ch[0]].tr[c^t[t[rt].ch[1]].sum^t[rt].val];
    }
    t[rt].tl[t[t[rt].ch[0]].sum^t[rt].val]++;
    t[rt].tr[t[t[rt].ch[1]].sum^t[rt].val]++;
    for(int c:{0,1}){
        t[rt].tl[c]+=t[rt].t[c^t[t[rt].ch[0]].sum^t[rt].val];
        t[rt].tr[c]+=t[rt].t[c^t[t[rt].ch[1]].sum^t[rt].val];
    }
}
void pushrev(int rt){
	if(!rt)return;
	t[rt].rev^=1;
	swap(t[rt].ch[0],t[rt].ch[1]);
    for(int c:{0,1}){
        swap(t[rt].tl[c],t[rt].tr[c]);
    }
}
void pushdown(int rt){
	if(t[rt].rev){
		pushrev(t[rt].ch[0]);
		pushrev(t[rt].ch[1]);
		t[rt].rev=0;
	}
}
bool isroot(int rt){
	return t[t[rt].fa].ch[0]!=rt&&t[t[rt].fa].ch[1]!=rt;
}
bool which(int rt){
	return t[t[rt].fa].ch[1]==rt;
}
void rotate(int x){
	int y=t[x].fa,z=t[y].fa,k=which(x);
	t[x].fa=z;
	if(!isroot(y))t[z].ch[which(y)]=x;
	if(t[y].ch[k]=t[x].ch[k^1])t[t[x].ch[k^1]].fa=y;
	t[x].ch[k^1]=y,t[y].fa=x;
	pushup(y),pushup(x);
}
void update(int x){
	if(!isroot(x))update(t[x].fa);
	pushdown(x);
}
void splay(int x){
	update(x);
	for(int y;y=t[x].fa,!isroot(x);rotate(x)){
		if(!isroot(y))rotate(which(x)^which(y)?x:y);
	}
}
void access(int x){
	int z=x;
	for(int y=0;x;y=x,x=t[x].fa){
		splay(x);
		pushdown(x);
        for(int c:{0,1}){
            t[x].t[c]-=t[y].tl[c];
            t[x].t[c]+=t[t[x].ch[1]].tl[c];
        }
		t[x].ch[1]=y;
		pushup(x);
	}
	splay(z);
}
void makeroot(int x){
	access(x);
	pushrev(x);
}
int findroot(int x){
	access(x);
	for(;t[x].ch[0];x=t[x].ch[0])pushdown(x);
	splay(x);
	return x;
}
void link(int x,int y){
	makeroot(x);
	if(findroot(y)==x)return;
	makeroot(y);
    access(x);
	t[y].fa=x;
    pushdown(x);
    t[x].ch[1]=y;
    pushup(x);
}
void modify(int x){
	access(x);
	t[x].val^=1;
	pushup(x);
}
