using ll=long long;
int solve(int a,int b,int c,int n){
	a=(a%c+c)%c;
	b=(b%c+c)%c;
	if(a>c/2)b=(1ll*a*n+b)%c,a=(c-a)%c;
	if(!a)return b;
	if(b>=a){
		int t=(c-b+a-1)/a;
		if(t>n)return b;
		n-=t;
		b=(b+a*t)-c;
	}
	if(!n)return b;
	if(a<=(c-1-b)/n)return b;
	return solve(-c,b,a,(1ll*a*n+b)/c);
}
