		for(j = 1; j < (1 << i); j++)
			rev[(1 << i) + j] = (rev[(1 << (i - 1)) + (j >> 1)] | ((j & 1) << (i - 1)));
		omg[1 << i] = 1;
		w = qpow(3, (mod - 1) >> i);
		for(j = 1; j < (1 << i); j++)
			omg[(1 << i) + j] = (ll)omg[(1 << i) + j - 1] * w % mod;
	}
}
ull tmp[1 << 21];
void ntt(int *A, int n, bool t)
{
	int i, j, k, w;
	for(i = 0; i < (1 << n); i++)
		tmp[i] = (A[rev[(1 << n) + i]] % mod + mod) % mod;
	for(i = 1; i < (1 << n); i <<= 1)
	{
		for(j = 0; j < (1 << n); j += (i << 1))
			for(k = 0; k < i; k++)
			{
				w = (ll)omg[(i << 1) + k] * tmp[i + j + k] % mod;
				tmp[i + j + k] = tmp[j + k] + mod - w;
				tmp[j + k] = tmp[j + k] + w;
			}
		if(i == (1 << 16))
			for(j = 0; j < (1 << n); j++)
				tmp[j] %= mod;
	}
	for(i = 0; i < (1 << n); i++)
		A[i] = tmp[i] % mod;
	if(t)
	{
		w = qpow(1 << n, mod - 2);
		for(i = 0; i < (1 << n); i++)
			A[i] = (ll)A[i] * w % mod;
		reverse(A + 1, A + (1 << n));
	}
}
struct poly
{
	vector<int> c;
	poly()
	{
		c.clear();
	}
	poly(vector<int> v)
	{
		c = v;
	}
	poly operator + (poly p)
	{
		int i;
		p.c.resize(max(p.c.size(), c.size()));
		for(i = 0; i < p.c.size(); i++)
			if(i < c.size())
				p.c[i] = (p.c[i] + c[i]) % mod;
		return p;
	}
	friend poly operator * (poly f, poly g)
	{
		if(f.c.empty() || g.c.empty())
			return poly();
		poly h;
		int i, l = 0;
		while((f.c.size() + g.c.size()) >> l)
			l++;
		memset(X, 0, 4 << l);
		memset(Y, 0, 4 << l);
		for(i = 0; i < f.c.size(); i++)
			X[i] = f.c[i];
		for(i = 0; i < g.c.size(); i++)
			Y[i] = g.c[i];
		ntt(X, l, 0);
		ntt(Y, l, 0);
		for(i = 0; i < (1 << l); i++)
			X[i] = (ll)X[i] * Y[i] % mod;
		ntt(X, l, 1);
		h.c.resize(f.c.size() + g.c.size() - 1);
		for(i = 0; i < h.c.size(); i++)
			h.c[i] = X[i];
		return h;
	}
};
int qwq(int x)
{
	return x > mod / 2 ? x - mod : x;
}
int a[N], b[N], c[N];
void work(int l, int r)
{
	int mid = (l + r) >> 1, i;
	if(l >= r)
		return ;
	poly f, g;
	for(i = l; i <= mid; i++)
		f.c.emplace_back(a[i]);
	for(i = mid + 1; i <= r; i++)
		g.c.emplace_back(b[i]);
	f = f * g;
	for(i = 0; i < f.c.size(); i++)
		c[i + l + mid + 1] = (c[i + l + mid + 1] + f.c[i]) % mod;
	work(l, mid);
	work(mid + 1, r);
	return ;
}

