const int N=2e5+5;
const ll mod=998244353;
int n,a[N];
ll fac[N],inv[N],sum[N],f[N],ans;
ll C(int n,int m){
	if(n<m||n<0||m<0)return 0;
	return fac[n]*inv[m]%mod*inv[n-m]%mod;
}
ll Pow(ll a,ll b){
	ll rec=1;
	for(;b;b>>=1,a=a*a%mod)
		if(b&1)rec=rec*a%mod;
	return rec;
}
void init(int n){
	fac[0]=1;
	for(int i=1;i<=n;i++)fac[i]=fac[i-1]*i%mod;
	inv[n]=Pow(fac[n],mod-2);
	for(int i=n-1;i>=0;i--)inv[i]=inv[i+1]*(i+1)%mod;
	for(int i=0;i<=n;i++)sum[i]=(C(n,i)+(i>=2?sum[i-2]:0))%mod;
}
int main(){
	scanf("%d",&n);
	for(int i=1;i<=2*n;i++)scanf("%d",&a[i]);
	sort(a+1,a+2*n+1);init(2*n);
	for(int i=1;i<=2*n;i++){
		int t=min(i,n);
		f[i]=t*C(2*n,i)%mod;
		if(2*t-i-1>=0)f[i]=(f[i]-sum[2*t-i-1]+mod)%mod;
	}for(int i=1;i<=2*n;i++)ans=(ans+(a[i]-a[i-1])*f[2*n-i+1]%mod*fac[i-1]%mod*fac[2*n-i+1])%mod;
	printf("%lld\n",ans*inv[2*n]%mod);
}

