#define ll long long
void solve(){
    ll S,T;scanf("%lld%lld",&S,&T);
    {ll val=sqrt(S+T);if(val*val==S+T)return printf("1 %lld\n",T),void();}
    if(S%2!=T%2){
        ll val=abs(S-T)/2+1;
        if(val*val>=max(S,T))return printf("2 %lld %lld\n",val*val-max(S,T),T),void();
    }
    if(S%4==T%4){
        ll val=abs(S-T)/4+1;
        if(val*val>=max(S,T))return printf("2 %lld %lld\n",val*val-max(S,T),T),void();
    }
    ll val=4.5e4;
    if(val%2==(S+T)%2)val++;
    ll vall=abs(val*val-S-T)/2+1;
    printf("3 %lld %lld %lld\n",val*val-S,vall*vall-max(val*val-S,T),T);
}
int main(){
    int _;scanf("%d",&_);
    while(_--)solve();
