	for(int i=17,&x=g[now][0]=now;i>=0;i--)
	{
		if(s[now]-s[f[x][i]]<=C)
		{
			x=f[x][i];
		}
	}
	g[now][0]=max(1,g[now][0]);
	for(int i=1;i<18;i++)
	{
		g[now][i]=max(1,
		g[g[now][i-1]][i-1]);
	}
	for(int i=0;i<e[now].size();i++)
	{
		int t=e[now][i].first;
		int v=e[now][i].second;
		if(t==f[now][0])
		{
			continue;
		}
		f[t][0]=now;
		s[t]=s[now]+v;
		d[t]=d[now]+1;
		dfs(t);
	}
}
int LCA(int x,int y)
{
	if(d[x]<d[y])
	{
		swap(x,y);
	}
	while(d[x]>d[y])
	{
		x=f[x][__lg(d[x]-d[y])];
	}
	if(x==y)
	{
		return x;
	}
	for(int i=17;i>=0;i--)
	{
		if(f[x][i]!=f[y][i])
		{
			x=f[x][i],y=f[y][i];
		}
	}
	return f[x][0];
}
