    Hash operator-(const Hash&t){return Hash((a-t.a+mod)%mod,(b-t.b+mod)%mod);}
    Hash operator*(const int&t){return Hash(a*pw1[t]%mod,b*pw2[t]%mod);}
    bool operator<(const Hash&t)const{return pi(a,b)<pi(t.a,t.b);}
    friend ostream&operator<<(ostream&o,Hash t){return o<<'('<<t.a<<','<<t.b<<')';}
