#include<bits/stdc++.h>
using namespace std;
 
typedef double ftype;
 
const ftype eps=1e-12;
const ftype pi=acos(ftype(-1));
 
int sgn(ftype x)
{
    if(x>eps)return 1;
    if(x<-eps)return -1;
    return 0;
}
 
struct Point3D
{
    ftype x,y,z;
    Point3D() {}
    Point3D(ftype x,ftype y,ftype z):x(x),y(y),z(z) {}
    Point3D operator + (const Point3D& t)const { return Point3D(x+t.x,y+t.y,z+t.z); }
    Point3D operator - (const Point3D& t)const { return Point3D(x-t.x,y-t.y,z-t.z); }
    Point3D operator - ()const { return Point3D(-x,-y,-z); }
    Point3D operator * (ftype t)const { return Point3D(x*t,y*t,z*t); }
    Point3D operator / (ftype t)const { return Point3D(x/t,y/t,z/t); }
    Point3D operator * (const Point3D& t)const { return Point3D(y*t.z-z*t.y,z*t.x-x*t.z,x*t.y-y*t.x); }
    ftype operator | (const Point3D& t)const { return x*t.x+y*t.y+z*t.z; }
    ftype sqr()const { return (*this)|(*this); }
    ftype len()const { return sqrt(sqr()); }
    Point3D unit()const { return (*this)/len(); }
    ftype angle(const Point3D& p)const { return atan2(((*this)*p).len(),(*this)|p); }
    ftype smallAngle(const Point3D& p)const { return atan2(((*this)*p).len(),abs((*this)|p)); }
};
 
struct Plane;
struct Line3D
{
    Point3D o,d;
    Line3D() {}
    Line3D(const Point3D& p,const Point3D& q):o(p),d(q-p) {}
    Point3D proj(const Point3D& p)const { return o+d*(d|(p-o))/d.sqr();}
    Point3D refl(const Point3D& p)const { return proj(p)*2-p; }
    ftype sqrDist(const Point3D& p)const {return (d*(p-o)).sqr()/d.sqr(); }
    ftype dist(const Point3D& p)const { return sqrt(sqrDist(p)); }
    ftype angle(const Line3D& l)const { return d.smallAngle(l.d); }
    ftype angle(const Plane& p)const;
    pair<int,Point3D> operator & (const Plane& p)const;
};
 
struct Plane
{
    Point3D n;
    ftype d;
    Plane(const Point3D& n,ftype d):n(n),d(d) {}
    Plane(const Point3D& n,const Point3D& p):n(n),d(n|p) {}
    ftype side(const Point3D& p)const { return (n|p)-d; }
    ftype dist(const Point3D& p)const { return abs(side(p))/n.len(); }
    ftype angle(const Line3D& l)const { return pi/2-n.smallAngle(l.d); }
    ftype angle(const Plane& p)const { return n.smallAngle(p.n); }
    Plane translate(const Point3D& t)const { return Plane(n,d+(n|t)); }
    Plane shiftUp(ftype dist)const { return Plane(n,d+dist*n.len()); }
    Point3D proj(const Point3D& p)const { return p-n*side(p)/n.sqr(); }
    Point3D refl(const Point3D& p)const { return proj(p)*2-p; }
    pair<int,Point3D> operator & (const Line3D& l)const { return l&(*this); }
    pair<int,Line3D> operator & (const Plane& p)const;
};
ftype Line3D::angle(const Plane& p)const { return p.angle(*this); }
pair<int,Point3D> Line3D::operator & (const Plane& p)const
{
    if(sgn(p.n|d)==0)return {0,Point3D()};
    return {1,o-d*p.side(o)/(p.n|d)};
}
pair<int,Line3D> inter(const Plane& p1,const Plane& p2)
{
    Line3D l;
    l.d=p1.n*p2.n;
    if(sgn(l.d.len())==0)return {0,Line3D()};
    l.o=(p2.n*p1.d-p1.n*p2.d)*l.d/l.d.sqr();
    return {1,l};
}
pair<int,Line3D> Plane::operator & (const Plane& p)const { return inter(*this,p); }
 
struct Sphere
{
    Point3D o;
    ftype r;
    Sphere(const Point3D& o,ftype r):o(o),r(r) {}
    pair<int,array<Point3D,2>> operator & (const Line3D& l)const
    {
        ftype h2=r*r-l.sqrDist(o);
        if(sgn(h2)<0)return {0,{}};
        Point3D p=l.proj(o);
        if(sgn(h2)==0)return {1,{p}};
        Point3D h=l.d*sqrt(h2)/l.d.len();
        return {2,{p-h,p+h}};
    }
    ftype greatCircleDist(const Point3D& a, const Point3D& b)const { return r*(a-o).angle(b-o); }
    ftype angleSph(const Point3D& a, const Point3D& b, const Point3D& c)const { return ((a-o)*(b-o)).angle((a-o)*(c-o)); }
    ftype orientedAngleSph(const Point3D& a, const Point3D& b, const Point3D& c)const
    {
        if(sgn((a-o)*(b-o)|(c-o))>=0)return angleSph(a,b,c);
        else return 2*pi-angleSph(a,b,c);
    }
    ftype areaOnSphere(const vector<Point3D>& p)const
    {
        int n=p.size();
        ftype sum=0;
        for(int i=0;i<n;i++)
            sum+=orientedAngleSph(p[(i+1)%n],p[(i+2)%n],p[i]);
        return r*r*(sum-(n-2)*pi);
    }
};
 
struct Point2D
{
    ftype x,y;
    Point2D(){}
    Point2D(ftype _x,ftype _y):x(_x),y(_y){}
    bool operator < (const Point2D& t)const
    {
        return x*t.y>y*t.x;
    }
};
Point2D distancePointToSegment(const Point3D& p,const Point3D& s,const Point3D& t)
{
    if(sgn((s*t)*s|p)>0 && sgn((s*t)*t|p)<0)
        return Point2D((p*(s*t)).len(),abs(p|(s*t)));
    return min(Point2D(p|s,(p*s).len()),Point2D(p|t,(p*t).len()));
}
 
const ftype EPS=1e-9;
 
int SGN(ftype x)
{
    if(x>EPS)return 1;
    if(x<-EPS)return -1;
    return 0;
}
 
bool check(int u,const vector<Point3D>& p,const int k,const ftype t)
{
    const int n=p.size()/2;
    auto cal=[&](const Point3D& q)
    {
        static vector<Point2D> val;
        val.resize(n);
        for(int i=0;i<n;i++)
            val[i]=distancePointToSegment(q,p[2*i],p[2*i+1]);
        nth_element(val.begin(),val.begin()+k,val.end());
        return SGN(atan2(val[k].y,val[k].x)-t)>=0;
    };
    vector<Plane> cur,all;
    const ftype ct=cos(t);
    for(int i=0;i<2*n;i++)
    {
        if(i/2==u)cur.emplace_back(p[i],ct*p[i].len());
        all.emplace_back(p[i],ct*p[i].len());
    }
    if(t<pi/2)
    {
        const ftype st=sin(t);
        for(int i=0;i<n;i++)
        {
            Point3D n=p[2*i]*p[2*i+1];
            if(i==u)
            {
                cur.emplace_back(n,st*n.len());
                cur.emplace_back(-n,st*n.len());
            }
            all.emplace_back(n,st*n.len());
            all.emplace_back(-n,st*n.len());
        }
    }
    Sphere s(Point3D(0,0,0),1);
    for(size_t i=0;i<cur.size();i++)
        for(size_t j=0;j<all.size();j++)
        {
            auto [r1,t1]=cur[i]&all[j];
            if(!r1)continue;
            auto [r2,t2]=s&t1;
            for(int r=0;r<r2;r++)
            {
                auto v=distancePointToSegment(t2[r],p[2*u],p[2*u+1]);
                if(SGN(atan2(v.y,v.x)-t)==0 && cal(t2[r]))return 1;
            }
        }
    return 0;
}
int solve()
{
    int n,k,r;
    scanf("%d%d%d",&n,&k,&r);
    vector<Point3D> p(2*n);
    for(int i=0;i<2*n;i++)
    {
        int tx,ty,tz;
        scanf("%d%d%d",&tx,&ty,&tz);
        p[i]=Point3D(tx,ty,tz);
    }
    vector<int> ord(n);
    iota(ord.begin(),ord.end(),0);
    static std::mt19937 rng(std::chrono::steady_clock::now().time_since_epoch().count());
    shuffle(ord.begin(),ord.end(),rng);
    ftype res=0;
    for(auto u : ord)
    {
        if(!check(u,p,k,res+EPS*3))continue;
        ftype tl=res,tr=pi;
        while(SGN(tr-tl)>0)
        {
            ftype tm=(tl+tr)/2;
            if(check(u,p,k,tm))tl=tm;
            else tr=tm;
        }
        res=(tl+tr)/2;
    }
    return 0*printf("%.12f\n",res*r);
}
