int check(ll mid)
{
	__int128 now=0;
	for(int i=1;i<=n;i++)
	{
		now*=k;
		if(now>=1e18)return 1;
		if(now<=-1e18)return -1;
		if(i&1)now+=mid-a[i];
		else now-=mid-a[i];
	}
