#include<bits/stdc++.h>
#define ld long double
#define sz(a) ((int)a.size())
using namespace std;
struct poly {
	vector <ld> f,g; //f(x)+g(x)*e^{-x}
	ld Z(ld x) {
		ld u=0,v=0;
		for(int i=sz(f)-1;~i;--i) u=u*x+f[i];
		for(int i=sz(g)-1;~i;--i) v=v*x+g[i];
		return u+expl(-x)*v;
	}
	poly Int() {
		vector <ld> a(sz(f)+1),b(sz(g));
		for(int i=1;i<=sz(f);++i) a[i]=f[i-1]/i;
		for(int i=sz(g)-1;~i;--i) b[i]=(i+1<sz(g)?(i+1)*b[i+1]:0)-g[i];
		return {a,b};
	}
	poly inp(ld t,ld w) { //a'=f-a
		vector <ld> a(sz(f)),b(sz(g)+1);
		for(int i=sz(f)-1;~i;--i) a[i]=f[i]-(i+1<sz(f)?(i+1)*a[i+1]:0);
		for(int i=1;i<=sz(g);++i) b[i]=g[i-1]/i;
		ld u=0,v=0;
		for(int i=sz(a)-1;~i;--i) u=u*t+a[i];
		for(int i=sz(b)-1;~i;--i) v=v*t+b[i];
		b[0]+=(w-u)*expl(t)-v;
		return {a,b};
	}
};
struct info {
	ld l,r; poly f;
	bool qry(ld&t,ld&w) {
		ld v=t+1,c=v*w; poly s=f.Int();
		if((c+s.Z(r)-s.Z(l))/(v+r-l)<f.Z(r)) return t=r,w=(c+s.Z(t)-s.Z(l))/(v+t-l),1;
		if(w>=f.Z(l)) return 0;
		ld L=l,R=r,m;
		for(int _=80;_--;) {
			m=(L+R)/2,((c+s.Z(m)-s.Z(l))/(v+m-l)<f.Z(m)?L=m:R=m);
		}
		t=L,w=(c+s.Z(t)-s.Z(l))/(v+t-l);
		return 0;
	}
};
void solve() {
	int n; ld X,z=0; cin>>n>>X,X/=1000;
	vector <info> f{{0,X,{{0},{}}}},g;
	for(int i=1,k;i<=n;++i,f.swap(g)) {
		ld t=0,w; cin>>w,w/=1000,g.clear();
		for(k=0;k<sz(f)&&f[k].qry(t,w);++k);
		g.push_back({0,t,{{w},{}}});
		for(;k<sz(f);++k) {
			f[k].l=max(f[k].l,t);
			g.push_back({f[k].l,f[k].r,f[k].f.inp(f[k].l,w)});
			w=g.back().f.Z(f[k].r);
		}
	}
	for(auto&o:f) z+=o.f.Int().Z(o.r)-o.f.Int().Z(o.l);
	cout<<fixed<<setprecision(20)<<z<<"\n";
}
signed main() {
	ios::sync_with_stdio(false),cin.tie(0),cout.tie(0);
	int _; cin>>_;
	while(_--) solve();
	return 0;
}

