	int c1[maxn],c2[maxn],all1,all2;
	void init(int n){
		all1=all2=0;
		For(i,0,n)c1[i]=c2[i]=0;
	}
	void add(int u,int w){
		int x=u;
		all1+=w;
		all2+=w*u;
		for(++x;x<=n;x+=x&-x) c1[x]+=w,c2[x]+=u*w;
	}
	int ask(int k){
		int res=0;
		k=all1-k;
		if(k<=0)return all2;
		int p=0;
		Rep(i,19,0) 
			if(p+(1<<i)<=n && c1[p+(1<<i)]<k) 
				p+=(1<<i),k-=c1[p],res+=c2[p];
		++p; res+=(p-1)*k;
//		Rep(i,n,1)if(c[i]){
//			int cnt=min(c[i],k);
//			k-=cnt,res+=i*cnt;
//			if(!k)break;
//		}
		return all2-res;
	}
}d1;

struct DS2{
	int c1[maxn],c2[maxn],all;
	void init(int n){
		all=0;
		For(i,0,n)c1[i]=c2[i]=0;
	}
	void add(int u,int w){
		int x=u;
		all+=w;
		for(++x;x<=n;x+=x&-x) c1[x]+=w,c2[x]+=u*w;
	}
	int ask(int k){
		int res=0,s1=0;
		for(int x=k+1;x;x^=x&-x) s1+=c1[x],res+=c2[x];
		res+=(all-s1)*k;
	//	For(i,1,n)if(c[i])res+=min(i,k)*c[i];
		return res;
	}
}d2;

int pos;
void add(int ii,int w){
	int u=id[n-ii+1];
	if(u<=x) d1.add(a[u].se-(x-1),w);
	else d2.add(n,-w),d2.add(a[u].se,w);
}
void move(int u){
	while(pos<u)add(++pos,1);
	while(pos>u)add(pos--,-1);
}
int ask(int k){
	return d1.ask(k)-d2.ask(k);
}

void solve(int l,int r,int kl,int kr)
{
	if(l>r)return;
	int mid=l+r>>1;
	move(mid);
	pii mx=mkp(-inf,-inf);
	For(k,kl,kr){
		int t=ask(k);
		mx=max(mx,mkp(t,k));
	}
	pk[mid]=mx.se;
	del[mid]=mx.fi;
	solve(l,mid-1,kl,pk[mid]);
	solve(mid+1,r,pk[mid],kr);
}

void work(int O)
{
