		return u.se>v.se;
	});
	For(i,1,n)id[i]=i;
	sort(id+1,id+n+1,[&](int u,int v){
		return a[u].fi<a[v].fi;
	});
	For(i,1,n)rk[id[i]]=i;
	For(i,1,n)b[i]=a[i];
	
	x=0;
	For(i,1,n){
		if(a[i].se>=i-1) x=i;
	}
	
	// choose how many left?
	pos=0,d1.init(n),d2.init(n);
	d2.add(n,n-x);
	solve(1,n,0,x);
//	For(i,1,n){
//		cout<<"k,del "<<pk[i]<<" "<<del[i]<<"\n";
//	}
	For(i,1,n){
		ans[i]=del[i];
