		int u=id[n-i+1];
		res+=dd*a[u].fi;
		if(u<=x) a[u].se-=dd;
		else a[u].se+=dd;
	}
	
	int odd=0;
	For(i,1,n)odd^=(a[i].se&1);
	if(odd){
		int mn=inf;
		For(i,1,n)mn=min(mn,a[i].fi);
		res+=mn;
	}
	cout<<res<<"\n";
}

