void solve(){
	n=rd(),m=rd();
	for(int i=1;i<=n;i++)G[i].clear(),a[i]=rd(),q.push({a[i],i}),vis[i]=0,F[i]=i;
	for(int i=1,u,v,w;i<=m;i++)u=rd(),v=rd(),w=rd(),G[u].push_back({v,w}),G[v].push_back({u,w}),E[i]={u,v,w};
