		return cout<<z<<"\n",void();
	}
	ll L=a[p]-A,R=a[p]+A,o=0,c=(A+B)/2;
	map <ll,array<ll,2>> f;
	auto add=[&](ll l,ll r,ll x,ll y) {
		l=max(l,L),r=min(r,R);
		if(l<=r) f[l][0]+=x,f[l][1]+=y,f[r+1][0]-=x,f[r+1][1]-=y;
	};
