using namespace std;
typedef long long ll;

const int N = 1e4 + 5, mod = 998244353;
bool ok[N][N], vis[N];
int a[N], c[N];
int F[N], G[N];

int main()
{
	int n, m, i, j, x;
	scanf("%d%d", &n, &m);
	n *= 2;
	for(i = 1; i <= n; i++)
	{
		a[i] = i;
		vis[i] = 1;
		for(j = i + 1; j <= n; j++)
			ok[i][j] = 1;
	}
	while(m--)
	{
		scanf("%d", &x);
		for(i = x + 1; i <= n; i++)
			ok[a[x]][a[i]] = ok[a[i]][a[x]] = 0;
		vis[a[x]] = 0;
		swap(a[x - 1], a[x]);
	}
	for(i = 1; i <= n; i++)
		for(j = i + 1; j <= n; j++)
			c[i] += ok[i][j];
	F[0] = 1;
	for(i = n; i >= 1; i--)
	{
		for(j = 0; j <= (n - i + 1) / 2; j++)
			G[j] = F[j];
		if(vis[i])
			for(j = 0; j <= (n - i) / 2; j++)
				F[j + 1] = (F[j + 1] + (c[i] + mod - 2ll * j) * G[j]) % mod;
		else
			for(j = 0; j <= (n - i) / 2; j++)
				F[j + 1] = (F[j + 1] + (ll)c[i] * G[j]) % mod;
	}
	printf("%d\n", F[n / 2]);
	return 0;
}

#include<bits/stdc++.h>
using namespace std;using ll=long long;using i128=__int128_t;
struct E{int u,v,q;ll w;};
struct G{vector<ll> p;vector<int> co;};
struct Rg{int u,c0,c1;ll p,l,r;};
ll n;int m,N;vector<E> e;vector<ll> ps,ln,TS;vector<G> gs;
ll fd(ll a,ll b){if(b<0)a=-a,b=-b;return a>=0?a/b:-((-a+b-1)/b);}
i128 cless(ll pa,ll a,ll b,ll pb,ll c,ll d){
    if(a>b||c>d)return 0;
    ll K=pa-pb+1;i128 r=0,x=min(b,c-K);
    if(a<=x)r+=(i128)(x-a+1)*(d-c+1);
    ll l=max(a,c-K+1),rr=min(b,d-K);
    if(l<=rr){i128 k=rr-l+1;r+=k*(d-K+1)-(i128)(l+rr)*k/2;}
    return r;
}
i128 ceq(Rg A,Rg B,ll C,bool le){
    int a=-(A.c0-A.c1),b=B.c0-B.c1;
    ll la=A.l,ra=A.r,lb=B.l,rb=B.r;
    auto ct=[&](ll s)->i128{ll L=lb,R=rb,K=A.p+s-B.p;if(le)L=max(L,K+1);else R=min(R,K-1);return L<=R?R-L+1:0;};
    auto cs=[&](ll t)->i128{ll L=la,R=ra,K=B.p+t-A.p;if(le)R=min(R,K-1);else L=max(L,K+1);return L<=R?R-L+1:0;};
    if(!a&&!b){if(C)return 0;return le?cless(A.p,la,ra,B.p,lb,rb):cless(B.p,lb,rb,A.p,la,ra);}
    if(!b){if(C%a)return 0;ll s=C/a;return s<la||s>ra?0:ct(s);}
    if(!a){if(C%b)return 0;ll t=C/b;return t<lb||t>rb?0:cs(t);}
    ll L=la,R=ra,Ac=-a*b,Bc=C*b;
    if(Ac==1)L=max(L,lb-Bc),R=min(R,rb-Bc);else L=max(L,Bc-rb),R=min(R,Bc-lb);
    if(L>R)return 0;
    ll M=B.p+Bc-A.p;
    if(Ac==1)return (le?(A.p<B.p+Bc):(A.p>B.p+Bc))?(i128)(R-L+1):0;
    if(le)R=min(R,fd(M-1,2));else L=max(L,fd(M,2)+1);
    return L<=R?(i128)(R-L+1):0;
}
int chk(ll T){
    static ll d[5005];static int pv[5005],pe[5005];
    for(int i=0;i<N;i++)d[i]=0,pv[i]=0,pe[i]=-1;
    int last=-1;
    for(int it=0;it<N;it++){
        last=-1;
        for(int id=0;id<(int)e.size();id++){
            auto &x=e[id];ll w=x.w-(ll)x.q*T;
            if(d[x.v]>d[x.u]+w)d[x.v]=d[x.u]+w,pv[x.v]=x.u,pe[x.v]=id,last=x.v;
        }
        if(last<0)return 0;
    }
    int y=last;for(int i=0;i<N;i++)y=pv[y];
    ll Q=0;int z=y;
    do{int k=pe[z];if(k<0)return 2;Q+=e[k].q;z=pv[z];}while(z!=y);
    if(!Q)return 2;
    return Q>0?1:-1;
}
G build(ll T){
    vector<ll> p(N,0);
    for(int it=0;it<N-1;it++){
        bool ch=0;
        for(auto &x:e){ll w=x.w-(ll)x.q*T;if(p[x.v]>p[x.u]+w)p[x.v]=p[x.u]+w,ch=1;}
        if(!ch)break;
    }
    vector<vector<int>> z(N);
    for(auto &x:e){ll w=x.w-(ll)x.q*T;if(p[x.v]==p[x.u]+w)z[x.u].push_back(x.v);}
    vector<int> dfn(N),low(N),st,in(N),co(N,-1);int ti=0,cc=0;
    function<void(int)> dfs=[&](int u){
        dfn[u]=low[u]=++ti;st.push_back(u);in[u]=1;
        for(int v:z[u]){if(!dfn[v])dfs(v),low[u]=min(low[u],low[v]);else if(in[v])low[u]=min(low[u],dfn[v]);}
        if(low[u]==dfn[u]){while(1){int v=st.back();st.pop_back();in[v]=0;co[v]=cc;if(v==u)break;}cc++;}
    };
    for(int i=0;i<N;i++)if(!dfn[i])dfs(i);
    return {p,co};
}
bool okT(int k,int u,int v){return gs[k].co[u]==gs[k].co[v];}
ll valT(int k,int u,int v,int q){return gs[k].p[v]-gs[k].p[u]+TS[k]*q;}
bool okG(int u,int v,int q){
    ll z=0;
    for(int k=0;k<(int)TS.size();k++){
        if(!okT(k,u,v))return 0;
        ll x=valT(k,u,v,q);
        if(k&&x!=z)return 0;
        z=x;
    }
    return 1;
}
void out(i128 x){
    if(!x){cout<<0<<"\n";return;}
    string s;while(x)s.push_back('0'+x%10),x/=10;
    reverse(s.begin(),s.end());cout<<s<<"\n";
}
int main(){
    ios::sync_with_stdio(0);cin.tie(0);
    cin>>n>>m;
    struct Q{int t;ll l,r,v;};vector<Q>a(m);ps.push_back(0);
    for(auto &x:a){cin>>x.t>>x.l>>x.r>>x.v;ps.push_back(x.l-1);ps.push_back(x.r%n);}
    sort(ps.begin(),ps.end());ps.erase(unique(ps.begin(),ps.end()),ps.end());N=ps.size();
    map<ll,int> mp;for(int i=0;i<N;i++)mp[ps[i]]=i;
    ln.resize(N);for(int i=0;i<N;i++)ln[i]=(i+1<N?ps[i+1]:n)-ps[i];
    auto add=[&](int u,int v,int q,ll w){e.push_back({u,v,q,w});};
    for(int i=0;i<N;i++){int j=(i+1)%N,q=i==N-1;add(i,j,q,ln[i]);add(j,i,-q,0);}
    for(auto &r:a){
        int u=mp[r.l-1],v=mp[r.r%n],q=ps[v]<=ps[u];
        if(r.t!=1)add(u,v,q,r.v);
        if(r.t!=2)add(v,u,-q,-r.v);
    }
    ll L=0,R=n,LE=-1,RI=-1;
    while(L<=R){
        ll mid=(L+R)/2;int c=chk(mid);
        if(c==2){cout<<-1<<"\n";return 0;}
        if(c==0)LE=mid,R=mid-1;else if(c<0)L=mid+1;else R=mid-1;
    }
    if(LE<0){cout<<-1<<"\n";return 0;}
    L=0;R=n;
    while(L<=R){
        ll mid=(L+R)/2;int c=chk(mid);
        if(c==2){cout<<-1<<"\n";return 0;}
        if(c==0)RI=mid,L=mid+1;else if(c<0)L=mid+1;else R=mid-1;
    }
    if(RI<LE||chk(LE)||chk(RI)){cout<<-1<<"\n";return 0;}
    TS.push_back(LE);if(RI!=LE)TS.push_back(RI);if(LE+1<RI)TS.push_back(LE+1);
    sort(TS.begin(),TS.end());TS.erase(unique(TS.begin(),TS.end()),TS.end());
    for(ll t:TS)gs.push_back(build(t));
    vector<Rg> rg;
    for(int i=0;i<N;i++){
        rg.push_back({i,0,0,ps[i],0,0});
        if(ln[i]>1){
            int j=(i+1)%N,q=i==N-1,c0=0,c1=0;bool use=0;
            if(LE==RI){
                if(okT(0,i,j)){ll d=valT(0,i,j,q);if(d==0||d==ln[i])use=1,c0=c1=d==ln[i];}
            }else if(RI==LE+1){
                if(okT(0,i,j)&&okT(1,i,j)){
                    ll d0=valT(0,i,j,q),d1=valT(1,i,j,q);
                    if((d0==0||d0==ln[i])&&(d1==0||d1==ln[i]))use=1,c0=d0==ln[i],c1=d1==ln[i];
                }
            }else{
                if(okG(i,j,q)){ll d=valT(0,i,j,q);if(d==0||d==ln[i])use=1,c0=c1=d==ln[i];}
            }
            if(use)rg.push_back({i,c0,c1,ps[i],1,ln[i]-1});
        }
    }
    if(LE==RI){
        vector<i128> sm(N+5);
        for(auto &x:rg)sm[gs[0].co[x.u]]+=x.r-x.l+1;
        i128 z=n;for(auto x:sm)z+=x*(x-1);
        out(z);return 0;
    }
    i128 ans=0;bool two=RI==LE+1;
    for(auto &A:rg)for(auto &B:rg){
        if(two){
            for(int q=0;q<=1;q++)if(okT(0,A.u,B.u)&&okT(1,A.u,B.u)){
                ll C=valT(1,A.u,B.u,q)-valT(0,A.u,B.u,q);
                ans+=ceq(A,B,C,q==0);
            }
        }else{
            if(okG(A.u,B.u,0))ans+=cless(A.p,A.l,A.r,B.p,B.l,B.r);
            if(okG(A.u,B.u,1))ans+=cless(B.p,B.l,B.r,A.p,A.l,A.r);
        }
    }
    out(ans);
}

