				}
			}
			for(int i=1;i<=n;i++){
				int cnt=0;
				if(vis[i]){
					for(int j:g[i]) cnt+=(j<i&&vis[j])||j==p1||j==p2;
					printf("%d ",l<cnt?l++:r--);
				}
				else printf("%d ",getnum(i));
			}
			printf("\n"),write(p1),write(p2),printf("\n");
		}
		else{
			k=0;
			for(int i=1;i<=n;i++) scanf("%d",&a[i]),k=max(k,a[i]);
			int p1=read(),p2=read();
			vis[p1]=vis[p2]=1,printf("%d\n",k);
			for(int i=1,cnt=0;cnt<k-2;i++){
				int num=getnum(i);
				if(a[i]<num||a[i]>num+k-cnt-2) printf("%d ",i),vis[i]=1,cnt++;
			}
			if(!p2) printf("%d\n",p1);
			else printf("%d %d\n",p2,p1);
		}
		for(int i=1;i<=n;i++) vis[i]=0,g[i].clear();
	}
	return 0;
}
